/* احادیث پیش‌فرض: کتابخانهٔ احادیث شیعه (ارائه‌شده توسط کاربر) */
window.HD=([{"id":"d000","by":"zahra","ar":"بِسْمِ اللّهِ الرَّحْمنِ الرَّحيمِ. بِسْمِ اللّهِ النُّورِ بِسْمِ اللّهِ نُورِ النٌّورِ بِسْمِ اللّهِ نُورٌ عَلى نُورٍ بِسْمِ اللّهِ الَّذى هُوَ مُدَبِّرُ الأُمُورِ بِسْمِ اللّهِ الَّذى خَلَقَ النُّورَ مِنَ النُّورِ اَلْحَمْدُلِلّهِ الَّذى خَلَقَ النُّورَ مِنَ النُّورِ وَاَنْزَلَ النُّورَ عَلَى الطُّورِ فىكِتابٍ مَسْطُورٍ في رَقٍّ مَنْشُورٍ بِقَدَرٍ مَقْدُورٍ عَلى نَبِىٍّ مَحْبُورٍ... حديث","fa":"یکی از دعاهای معروف حضرت زهرا علیها السلام: به نام خداوند بخشنده مهربان، به نام خدایی که نور است، به نام خدایی که نور نور است، به نام خدایی که نوری بالای نور است، به نام خدایی که تدبیر امور به دست اوست، به نام خدایی که نور را از نور آفرید. ستایش و سپاس خدایی را که نور را از نور آفرید و نور را بر کوه طور فرود آورد، در درون کتابی نوشته شده، در طوماری گسترده بر پیامبری برخوردار از نعمتها.","at":"حضرت زهرا (س) — چهل حدیث «گهرهای فاطمی» (حدیث ۳۰۱)"},{"id":"d001","by":"zahra","ar":"اَيُّهَا النّاسُ اِعْلَمُوا اَنّى فاطِمَةُ وَاَبى مُحَمَّدٌ اَقُولُ عَوْدا وَبَدْءا وَلا اَقُولُ ما اَقُولُ غَلَطا وَلا اَفْعَلُ ما اَفْعَلُ شَطَطا. « لَقَدْ جاءَكُمْ رَسُولٌ مِنْ اَنْفُسِكُمْ عَزيزٌ عَلَيْهِ ما عَنِتُّمْ حَريصٌ عَلَيْكُمْ بِالْمُؤمِنينَ رَؤُوفٌ رَحيمٌ...» حديث","fa":"حضرت زهرا در بخشی از خطبه خود می فرماید: ای مردم! بدانید که من فاطمه ام و پدرم محمد صلی الله علیه و آلهاست. پایان و آغاز سخنم یکی است، نابجا سخن نمی گویم و به کار یاوه و بیهوده نمی پردازم. به حقیقت پیامبری از میان خودتان برخاست که رنجهای شما بر او دشوار بود و به هدایت و اصلاح شما حریص و بر مؤمنان دلسوز و مهربان بود.","at":"حضرت زهرا (س) — چهل حدیث «گهرهای فاطمی» (حدیث ۳۰۲)"},{"id":"d002","by":"zahra","ar":"كِتابُ اللّهِ النّاطِقُ وَالْقُرْانُ الصّادِقُ وَالنُّورُ السّاطِعُ وَالضِّياءُ الّلامِعُ، بَيِنَّةً بَصائِرُهُ، مُنْكَشِفَةً سَرائِرُهُ، مُنْجَلِيَةً ظَواهِرُهُ، مُغْتَبِطَةً بِهِ اَشْياعُهُ، قائدا اِلَى الرِّضْوانِ اِتِّباعُهُ، مُؤَدٍّ اِلَى النَّجاةِ اِسْتِماعُهُ. حديث","fa":"و در بخش دیگری از خطبه می فرماید:... کتاب گویای خداوند و قران راستگو و نور فروغ بخش و روشنایی درخشان عهد الهی و یادگار پیامبر است که دیدگاههایش روشن و اسرار درونی او بر ملا و ظاهر آن جلوه گر و پیروان او مورد غبطه همگان است. تبعیت از آن راهگشای دستیابی به رضای الهی و گوش سپردن به او موجب نجات است","at":"حضرت زهرا (س) — چهل حدیث «گهرهای فاطمی» (حدیث ۳۰۳)"},{"id":"d003","by":"zahra","ar":"كِتابُ اللّهِ بَيْنَ اَظْهُرِكُمْ اُمُورُهُ ظاهِرَةٌ وَاَحْكامُهُ زاهِرَةٌ وَاَعْلامُهُ باهِرَةٌ وَزَواجِرُهُ لائحَةٌ وَاَوامِرُهُ واضِحَةٌ... حديث","fa":"و در بخش دیگری از خطبه می فرماید: کتاب الهی فرا روی شماست، امور مربوط به او ظاهر و احکامش فروزان و نشانه هایش خیره کننده و فرامین بازدارنده اش آشکار و دستورهایش واضح است.","at":"حضرت زهرا (س) — چهل حدیث «گهرهای فاطمی» (حدیث ۳۰۴)"},{"id":"d004","by":"zahra","ar":"وَاحْمِدُوا اللّهَ الَّذى لِعَظَمَتِهِ وَنُورِهِ يَبْتَغى مَنْ فِى السَّماواتِ وَالْأرَضِ اِلَيْهِ الْوَسيلَةَ وَنَحْنُ وَسيلَتُهُ فى خَلْقِهِ وَنَحْنُ خاصَّتُهُ وَمَحَلُّ قُدْسِهِ وَنَحْنُ حُجَّتُهُ فى غَيْبِهِ وَنَحْنُ وَرَثَةُ اَنْبِيائِهِ... حديث","fa":"در پایان خطبه فرمود: سپاسِ خدایی را به جای آرید که به خاطر عظمت وجود و جلوه نورش هر آنچه در آسمانها و زمین است خواهان ره یافتن به سوی او هستند و در این میان تنها ما وسیله تقرب به او و بندگانِ برگزیده و پایگاه تقدیس و تنزیه او و حجت او در غیبت و نهان و وارث پیامبران اوییم.","at":"حضرت زهرا (س) — چهل حدیث «گهرهای فاطمی» (حدیث ۳۰۵)"},{"id":"d005","by":"zahra","ar":"قالَ جابِرُ... فَقُلتُ لَها: بِأبى أنتَ وَ اُمّى يا بِنتَ رَسُولِ اللّهِ، ما هذَا اللَّوحُ؟ فَقالَت: هذَا اللَّوْحُ اَهْداهُ اللّهُ عَزَّوَجَلَّ اِلى رَسُولِهِ صلي الله عليه و آلهفيهِ اسْمُ اَبى وَفيهِ اسْمُ بَعْلى وَاسْمُ ابْنَىَّ وَاَسْماءُ الْأَوْصِياءِ مِنْ وُلْدى. فَاَعْطانيهِ اَبى لِيَسُرَّنى بِذلِكَ. حديث","fa":"جابر بن عبداللّه می گوید: در دست فاطمه زهرا علیها السلام لوحی زمردین دیدم، پرسیدم: ای دختر رسولخدا پدر و مادرم فدای تو باد این چه لوحی است؟ حضرت فرمود: این لوح را که در آن نام پدر و شوهرم و دو پسرم و نامهای فرزندان معصومم نوشته شده است خدای عزوجل به پیامبرش هدیه نمود و پیامبر نیز برای خوشحالی من آن را به من داد.","at":"حضرت زهرا (س) — چهل حدیث «گهرهای فاطمی» (حدیث ۳۰۶)"},{"id":"d006","by":"zahra","ar":"لَكِ حَلاوَةُ الْوَلَدِ وَلَهُ عِزُّ الرِّجالِ وَهُوَ اَحَبُّ إلَىَّ مِنْكِ. فَقالَت فاطِمَةُ: وَالَّذِى اصْطَفاكَ واجْتَباكَ وَهَداكَ وَهَدى بِكَ الْأُمَّةَ لازِلْتُ مُقِرَّةً لَهُ ما عِشْتُ. حديث","fa":"در جمع گرم خانواده هر یک از علی و فاطمه خود را نزد پیامبر محبوبتر می شمردند، پیامبر به فاطمه فرمود: تو را حلاوت فرزندی و علی را عزّت مردان است و او نزد من محبوتر است.فاطمه گفت: به خدایی که تو را برگزید و هدایت کرد و امّت را به سبب تو راه نمود، همواره تا زنده ام به مقام او مقّر خواهم بود.","at":"حضرت زهرا (س) — چهل حدیث «گهرهای فاطمی» (حدیث ۳۰۷)"},{"id":"d007","by":"zahra","ar":"اَخْبَرَنَى اَبى وَهُوَذا: هُوَ اَنَّهُ مَنْ سَلَّمَ عَلَيْهِ وَعَلَىَّ ثَلاثَةَ اَيّامٍ اَوْجَبَ اللّهُ لَهُ الْجَنَّةَ. قالَ الرّاوى: قُلْتُ لَها: فى حَياتِهِ وَحَياتِكِ؟ قالَتْ عليهاالسلام: نَعَمْ وَبَعْدَ مَوْتِنا. حديث","fa":"حضرت زهرا علیها السلام فرمود: پدرم قبل از رحلتش به من فرمود: هر کس سه روز بر او و بر من درود فرستد خدا بهشت را بر او واجب گرداند. راوی می گوید: گفتم: در زندگی او و شما؟ حضرت زهرا علیها السلام فرمود: بلی هم در حال حیات، و هم پس از مرگ.","at":"حضرت زهرا (س) — چهل حدیث «گهرهای فاطمی» (حدیث ۳۰۸)"},{"id":"d008","by":"zahra","ar":"قالَ رَجُلٌ لاِءمرَأتِهِ: إذهَبى إلى فاطِمَةَ عليهاالسلامفَاسْأَليها أنّى مِن شيعَتِكُم؟... فَقالَت عليهاالسلام: قُولى لهُ: اِنْ كُنْتَ تَعْمَلُ بِما اَمَرْناكَ وَتَنْتَهى عَمّا زَجَرْناكَ عَنْهُ فَأَنْتَ مِنْ شيعَتِنا وَاِلاّ فَلا... حديث","fa":"شخصی به زنش گفت: پیش فاطمه زهرا علیها السلام برو و بپرس: آیا من از شیعیان اهل بیت هستم؟ زن آمد و پرسید، حضرت زهرا علیها السلام در پاسخ گفت: به همسرت بگو: اگر به آنچه ترا فرمان داده ایم عمل می کنی و از آنچه نهی کرده ایم پرهیز نموده ای از شیعیان خواهی بود و در غیر این صورت از شیعیان نیستی.","at":"حضرت زهرا (س) — چهل حدیث «گهرهای فاطمی» (حدیث ۳۰۹)"},{"id":"d009","by":"zahra","ar":"اَلّلهُمَّ اِنّى اَسْأَلُكَ قُوَّةً فى عِبادَتِكَ وَتَبَصُّرا فى كِتابِكَ وَفَهْما فى حُكْمِكَ، اَللّهُمَّ صَلِّ عَلى مُحَمَّدِ وَالِ مُحَمَّدٍ وَلاتَجْعَلِ الْقُرْانَ بِنا ماحِلاً وَالصِّراطَ زائِلاً وَمُحَمَّدا صَلَى اللّهُ عَلَيهِ وَالِهِ عَنّا مُوَلِّيا. حديث","fa":"یکی از دعاهای حضرت زهرا علیها السلام این بود: بارالها: نیرومندی در بندگیت و بینش روشن در کتابت و فهم و درک احکامت را از تو خواستارم. خدایا بر محمد و آل محمد درود فرست و قران را دور از دسترس ما و پل صراط را لغزشگاه ما و محمد صلی الله علیه و آله را رویگردان از ما قرار مده.","at":"حضرت زهرا (س) — چهل حدیث «گهرهای فاطمی» (حدیث ۳۱۰)"},{"id":"d010","by":"zahra","ar":"اَبَوا هذِهِ الْأُمَّةِ مُحَمَّدٌ وَ عَلِىٌّ يُقيمانِ اَوَدَهُمْ وَيُنْقِذانِهِمْ مِنَ الْعَذابِ الدّائِمِ اِنْ اَطاعُوهُما وَيُبيحانِهِمُ النَّعيمَ الدّائِم اِنْ وافَقُوهُما. حديث","fa":"حضرت زهرا علیها السلام فرمود: پدران این امّت حضرت محمد صلی الله علیه و آله پیامبر خدا و حضرت علی علیه السلام ولی خدا است. اگر از آن دو اطاعت کنند، کژی های آنان را اصلاح می کنند و از عذاب دردناکشان نجات می بخشند و همراهی با آن دو نعمت جاودان بهشت را ارزانیشان می دارد.","at":"حضرت زهرا (س) — چهل حدیث «گهرهای فاطمی» (حدیث ۳۱۱)"},{"id":"d011","by":"zahra","ar":"قالَت فاطِمَةُ عليهاالسلام لِرَجُلٍ لَمّا سَئَلَها وَ هِىَ عَلى قَبرِ عَمِّها حَمزَة عليه السلام: اَما وَاللّهِ لَوْ تَرَكُوا الْحَقَّ عَلى اَهْلِهِ وَاتَّبَعُوا عِتْرَةَ نَبِيِّهِ لَمَااخْتَلَفَ فِى اللّهِ تَعالى اثْنانِ. حديث","fa":"حضرت زهرا علیها السلام بر سر مزار حمزه علیه السلام در پاسخ شخصی می فرماید: به خدا سوگند اگر حق را به اهلش واگذار می نمودند و از عترت پیامبر پیروی می کردند، حتی دو نفر درباره خدا اختلاف نمی نمودند (واسلام همه عالم را فرا می گرفت.)","at":"حضرت زهرا (س) — چهل حدیث «گهرهای فاطمی» (حدیث ۳۱۲)"},{"id":"d012","by":"zahra","ar":"كَيفَ أَصبَحتِ عَن لَيلَتَكِ يا بِنتَ رَسُولِ اللّهِ صلي الله عليه و آله؟ قالَتْ: اَصْبَحْتُ بَيْنَ كَمَدٍ وَكَرْبٍ، فُقِدَ النَّبِىُّ وَظُلِمَ الْوَصِىُّ، هُتِكَ وَاللّهِ حِجابُهُ... حديث","fa":"روزی ام سلمه برای عیادت حضرت فاطمه علیها السلام آمد وپرسید: ای دختر پیامبر شب را چگونه به صبح آوردی (شب و روزت چگونه می گذرد)؟ حضرت علیها السلام فرمود: به صبح آوردم در حالی که تاریکی غم و انده مرا فراگرفته است، پیامبر از دست رفت و وصی او مظلوم واقع شد، حَریم و حرمت پیامبر شکسته شد.","at":"حضرت زهرا (س) — چهل حدیث «گهرهای فاطمی» (حدیث ۳۱۳)"},{"id":"d013","by":"zahra","ar":"قالَتْ فاطِمَةُ عليهاالسلام لِجَماعَةٍ مِنَ النِّساءِ لَمّا قُلنَ لَها: يا بِنتَ رَسُولِ اللّهِ كَيفَ أصبَحتِ مِن عِلَّتِكِ؟ فَقالَت: عليهاالسلام اَصْبَحْتُ وَاللّهِ عائِفَةً لِدُنْياكُنَّ، قالِيَةً لِرِجالِكُنَّ، لَفَظْتُهُمْ بَعْدَ اَنْ عَجَمْتُهُمْ وَشَنِأْتُهُمْ بَعْدَ اَنْ سَبَرْتُهُمْ، فَقُبْحا لِفُلُولِ الحَدِّ وَ خَوَرِ الْقناةِ وَ خَطَلِ الرَّأْىِ... حديث","fa":"حضرت زهرا علیها السلام در پاسخ زنانی که برای عیادتش آمده و از سلامتی اش سؤال کردند فرمود: به خدا سوگند صبح کردم در حالی که نسبت به دنیای شما بی رغبت و از مردان شما خشمگینم. پس از چشیدن، آنان را از دهان بیرون افکندم و پس از پیگیری، از آنان خسته شدم. چه زشت است کند شدن تلاش ها و سستی نیروها و اضطراب اندیشه ها! .","at":"حضرت زهرا (س) — چهل حدیث «گهرهای فاطمی» (حدیث ۳۱۴)"},{"id":"d014","by":"zahra","ar":"وَمَا الَّذى نَقَمُوا مِنْ اَبِى الْحَسَنِ عليه السلام؟ نَقَمُوا وَاللّهِ مِنْهُ نَكيرَ سَيْفِهِ وَقِلَّةَ مُبالاتِهِ لِحَتْفِهِ وَشِدَّةَ وَطْأَتِهِ وَنَكالَ وَقْعَتِهِ وَتَنَمُّرُهُ فى ذاتِ اللّهِ... حديث","fa":"حضرت زهرا علیها السلام در بخشی از سخنانش با زنان مدینه فرمود: به راستی آنان که دیگران را ترجیح دادند چه عیبی از ابوالحسن امیرالمؤمنین علیه السلام گرفتند؟ به خدا قسم تنها عیب علی شمشیر بران او و بی اعتنایی به مرگ و برخورد سخت و ضربه های مرگبار و خشم سرکش او در رابطه با دفاع از دین خداست.","at":"حضرت زهرا (س) — چهل حدیث «گهرهای فاطمی» (حدیث ۳۱۵)"},{"id":"d015","by":"zahra","ar":"وَكُنْتُمْ عَلى شَفا حُفْرَةٍ مِنَ النّارِ مُذْقَةَ الشّارِبِ وَنُهْزَةَ الطّامِعِ... فَاَنْقَذَكُمُ اللّهُ تَبارَكَ وَ تَعالى بِمُحَمَّدٍ صلي الله عليه و آله بَعْدَ اللَّتَيّا وَاللَّتى وَبَعْدَ اَنْ مُنِىَ بِبُهَمِ الرِّجالِ وَذُؤْبانِ الْعَرَبِ وَمَرَدَةِ اَهْلِ الْكِتابِ كُلَّما أوْقَدُوا نارا لِلْحَرْبِ اَطْفَأَهَااللّهُ، اَوْ نَجَمَ قَرْنُ الشَّيْطانِ اَوْ فَغَرَتْ فاغِرَةٌ مِنَ الْمُشْرِكينَ قَذَفَ اَخاهُ فى لَهَواتِها، فَلايَنْكَفِى ءُ حَتّى يَطَأَ جَناحَها بِاَخْمُصِهِ وَيَخْمِدَ لَهَبَها بِسَيْفِهِ... حديث","fa":"حضرت زهرا علیها السلام در بخش دیگری از خطبه می فرماید:... و شما بر لبه پرتگاهی از آتش قرار داشتید جرعه آبی برای تشنگان و شکار بی رنجی برای آزمندان بودید، آنگاه خدای بزرگ به وسیله حضرت محمد صلی الله علیه و آله و پس از چه فراز و نشیب ها و گرفتار شدن به دست مردان حیوان صفت و گرگان آدمخوار عرب و گردنکشان اهل کتاب نجاتتان بخشید. هرگاه که آتش جنگی بر می افروختند خدا خاموش می کرد و اگر شاخ شیطانی سرک می کشید و یا مرزی از سوی مشرکان گشوده می شد پیامبر، برادرش حضرت علی علیه السلام را در کام آن می افکند و او نیز تا هنگامی که یال و بال آنان با کف پای خود پایمال نمی کرد و آتش آنان را با شمشیر خاموش نمی ساخت بر نمی گشت.","at":"حضرت زهرا (س) — چهل حدیث «گهرهای فاطمی» (حدیث ۳۱۶)"},{"id":"d016","by":"zahra","ar":"وَتَاللّهِ لَوْمالُوا عَنِ الْمَحَجَّةِ اللاّئحَةِ وَزالُوا عَنْ قَبُولِ الْحُجَّةِ الْواضِحَةِ لَرَدَّهُمْ اِلَيْها وَحَمَلَهُمْ عَلَيها وَلَسْارَبِهِمْ سَيْرا سُجُحا لايَكْلِمُ خِشاشُهُ وَلايَكِلُّ سائِرُهُ وَلايَمُلُّ راكِبُهُ وَلَأَوْرَدَهُمْ مَنْهَلاً نَميرا صافِيا رَوِيّا... حديث","fa":"حضرت زهرا علیها السلام در بخش دیگری از سخنانش با زنان مدینه در مورد حضرت امیرالمؤمنین علیه السلام می فرماید: به خدا سوگند اگر از راه روشن منحرف می شدند و از پذیرش دلیل واضح می لغزیدند، آنان را به راه مستقمیم برگردانده و بر التزام به آن وامی داشت و با نرمی و ملایمت راهشان می برد، به گونه ای که خشونت و ناهمواری راه آنان را آزار نمی داد و رهروان را خسته نمی ساخت و سواران را ملول نمی کرد. و آنان را به آبشخوری پر برکت و زلال و گوارا رهنمون می شد","at":"حضرت زهرا (س) — چهل حدیث «گهرهای فاطمی» (حدیث ۳۱۷)"},{"id":"d017","by":"zahra","ar":"اَما لَعَمْرى لَقَدْ لَقِحَتْ فَنَظِرَةٌ رَيْثَما تُنْتِجْ ثُمَّ احْتَلِبُوا مِلْأَ الْقَعْبِ دَما عَبيطا وَذِعافا مُبيدا، هُنالِكَ يَخْسَرُ الْمُبْطِلُونَ وَيَعْرِفُ التّالُونَ غِبَّ ما اَسَّسَ الْأَوَّلُونَ، ثُمَّ طيبُوا عَنْ دُنْياكُمْ اَنْفُسا وَاطْمَأِنُّوا لِلْفِتْنَةِ جاشا وَاَبْشِرُوا بِسَيْفٍ صارِمٍ وَسَطْوَةَ مُعْتَدٍ غاشِمٍ وَبِهَرْجٍ شامِلٍ وَاِسْتِبْدادٍ مِنَ الظّالِمينَ، يَدَعُ فَيْئَكُمْ زَهيدا وَجَمْعَكُمْ حَصيدا فَياحَسْرَتا لَكُمْ وَاَنىّ بِكُمْ وَقَد عُمِّيَتْ عَلَيْكُمْ… حديث","fa":"حضرت زهرا علیها السلام در بخش پایانی سخنانش با زنان مدینه فرمود:... به جان خودم سوگند! نطفه فساد و تباهی بسته شد، اندکی منتظر باشید تابه نتیجه رسد آنگاه به جای شیر، کاسه های پر از خون تازه و زهر کشنده بدوشید و در آن هنگام گمراهان، زیان کجروی خود را خواهند دید و آیندگان پیامد کار پیشینیان را خواهند دانست. آنگاه دل از دنیا برکنید و با فتنه ها آرامش خاطر یابید! و مژده باد بر شما به شمشیر آخته و سلطه متجاوز ستمگر و نیز هرج و مرج فراگیر و استبداد زورگویان! همانان که بخش ناچیزی از حق را به شما برگردانند و اجتماع شما را درو کنند! چه حسرت بزرگی! و چه می توان کرد؟ در صورتی که امروز کورکورانه برده شده اید.","at":"حضرت زهرا (س) — چهل حدیث «گهرهای فاطمی» (حدیث ۳۱۸)"},{"id":"d018","by":"zahra","ar":"فَبِعَيْنِ اللّهِ ما تَفْعَلُونَ، وَسَيَعْلَمُ الَّذينَ ظَلَمُوا اَىَّ مُنْقَلَبٍ يَنْقَلِبُونَ، وَاَنَا ابْنَةُ نَذيرٍ لَكُمْ بَيْنَ يَدَىْ عَذابٍ شَديدٍ، فَاعْمَلُوا اِنّا عامِلُونَ، وَانْتَظِرُوا اِنّا مُنْتَظِرُونَ... حديث","fa":"حضرت زهرا علیها السلام در بخش دیگری از خطبه فرمود:... آنچه می کنید زیر نظر خداست و ستمگران به زودی خواهند دانست که به سوی چه سرانجامی باز می گردند! و من دختر کسی هستم که شما را از عذاب دردناک و سخت بیم می داد، پس هر چه خواهید بکنید ما نیز کار خود پیش می گیریم و منتظر باشید و ما نیز در انتظار به سر می بریم.","at":"حضرت زهرا (س) — چهل حدیث «گهرهای فاطمی» (حدیث ۳۱۹)"},{"id":"d019","by":"zahra","ar":"اَلّلهُمَّ اِلَيْكَ نَشْكُو فَقْدَ نَبِيِّكَ وَرَسُولِكَ وَصَفِيِّكَ وَارْتِدادَ اُمَّتِهِ وَمَنْعِهِمْ اِيّانا حَقَّنَا الذَّى جَعَلْتَهُ لَنا فى كِتابِكَ الْمُنْزَلِ عَلى نَبِيِّكَ بِلِسانِهِ. حديث","fa":"یکی دیگر از دعاهای حضرت زهرا علیها السلام: بارالها: درد جانکاه از دست دادن پیامبر و فرستاده برگزیده ات را به تو باز می گوییم و نیز عقبگرد امّتش و جلوگیری آنان از دسترسی ما به حقی را که تو در کتاب و برزبان پیامبرت تعیین کرده ای به تو شکایت می کنیم.","at":"حضرت زهرا (س) — چهل حدیث «گهرهای فاطمی» (حدیث ۳۲۰)"},{"id":"d020","by":"prophet","ar":"اَدِّبوا اَوْلادَكُم عَلى حُبّى و حُبِّ اَهلِ بَيتى وَ القرآنِ. حديث","fa":"پیامبر اکرم صلی الله علیه و آله فرمود: فرزندان خود را با محبت من و محبت اهل بیت من و محبت قرآن تربیت کنید.","at":"پیامبر اکرم (ص) — چهل حدیث «گهرهای نبوی» (حدیث ۱۰۱)","tip":"ایجاد پیوند میان نوجوانان و اهل بیت، مانع به فساد کشیده شدن آنان است."},{"id":"d021","by":"prophet","ar":"اِسْمَعُوا وَ اَطيعُوا لِمَنْ وَلاّهُ اللّهُ الأَمْرَ، فَاِنَّهُ نِظامُ الأسلامِ. حديث","fa":"پیامبر خدا صلی الله علیه و آله فرمود: از کسی که خداوند به او «ولایت امر» داده است، حرف شنوی و اطاعت داشته باشید، چرا که این اطاعت، نظام بخِش اسلام است.","at":"پیامبر اکرم (ص) — چهل حدیث «گهرهای نبوی» (حدیث ۱۰۲)","tip":"ولایت ورهبری، رمز وحدت و عزّت مسلمانان است."},{"id":"d022","by":"prophet","ar":"اَحْبِبْ فِى اللّهِ وَ ابْغِضْ فِى اللّهِ وَ والِ فِى اللّهِ وَ عادِ فِى اللّهِ فَاِنَّهُ لَنْ تُنالَ وُلاِيَةُ اللّهِ اِلاّ بِذلِك، وَ لايَجِدُ رَجُلٌ طَعْمَ الإيمانِ وَاِنْ كَثُرَتْ صَلاتُهُ وَ صِيامُهُ حَتّى يَكُونَ كَذلِك. حديث","fa":"حضرت رسول روزی به یکی از اصحاب خویش فرمود: در راه خدا دوست بدار و برای خدا دشمن بدار، برای خدا موالات ودوستی کن وبرای خدا دشمنی کن، یقینا جز با این، به ولایت خدا نخواهی رسید. و هرگز کسی طعم ایمان را نمی یابد، هر چند نماز و روزه اش فراوان باشد، مگر آنکه چنین باشد.","at":"پیامبر اکرم (ص) — چهل حدیث «گهرهای نبوی» (حدیث ۱۰۳)","tip":"عمق بخشیدن به محبّتها و کینه ها و بُعد مکتبی دادن به دوستی و دشمنی."},{"id":"d023","by":"prophet","ar":"حُبّى و حُبُّ اَهْلِ بَيْتى نافِعٌ فى سَبْعَةِ مَواطِنَ اَهْوالُهُنَّ عَظيمَةٌ: عِنْدَ الوَفاةِ و فِى الْقَبْرِ وَ عِنْدَالنُّشُورِ وَ عِنْدَالِكتابِ وَ عِنْدَ الحِسابِ وَ عِنْدَ الميزانِ وَ عِنْدَ الصِّراطِ. حديث","fa":"رسول خدا صلی الله علیه و آله فرمود: محبّت من و محبّت اهل بیت من در هفت جا که هراس آنها بسیار بزرگ است، سودمند است: ۱ هنگام مرگ، ۲ در قبر، ۳ هنگام برانگیخته شدن، ۴ هنگام دریافت نامه اعمال، ۵ هنگام حسابرسی، ۶ هنگام سنجش اعمال، ۷ هنگام عبور از صراط.","at":"پیامبر اکرم (ص) — چهل حدیث «گهرهای نبوی» (حدیث ۱۰۴)"},{"id":"d024","by":"prophet","ar":"اَيُّهَا النّاسُ! اِنَّ رَبَّكُمْ واحِدٌ و اِنَّ اَباكُمْ واحِدٌ كُلُّكُمْ لاِ?َمَ وَ آدَمُ مِنْ تُرابٍ «اِنَّ اَكرَمَكُمِْ عِنْدَ اللّهِ اَتْقيكُمْ» وَ لَيْسَ لِعَرَبىٍّ عَلى عَجَمِىٍّ فَضْلٌ اِلاّ بِالتَّقْوى. حديث","fa":"رسول خدا صلی الله علیه و آله در خطبه «حجّة الوداع» فرمود: ای مردم! پروردگارتان یکی است، پدرتان هم یکی است، همه شما از آدمید و آدم از خاک است. «گرامی ترین شما نزدخداوند، پرهیزکارترین شماست» عرب را بر عجم هیچ برتری نیست، مگر به تقوا.","at":"پیامبر اکرم (ص) — چهل حدیث «گهرهای نبوی» (حدیث ۱۰۵)","tip":"تفاخرات قومی و نژادی و افتخار به زبان و رنگ و... از نظر اسلام مردود است، تقوا ملاک برتری است."},{"id":"d025","by":"prophet","ar":"اَلْمُؤْمِنُ مَنْ اَمِنَهُ المُسلِمونَ عَلى اَمْوالِهِمْ وَدِمائِهِمْ وَالْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ يَدِهِ وَ لِسانِهِ، وَ الْمُهاجِرُ مَنْ هَجَرَ السَّيّئاتِ. حديث","fa":"پیامبر اسلام صلی الله علیه و آله فرمود: مؤمن کسی است که مسلمانان او را بر مال و جان خویش، امین بدانند، مسلمان کسی است که مسلمانان از دست و زبانش در امان باشند. مهاجر کسی است که از بدی ها هجرت کند و گناهان را واگذارد.","at":"پیامبر اکرم (ص) — چهل حدیث «گهرهای نبوی» (حدیث ۱۰۶)"},{"id":"d026","by":"prophet","ar":"مَنْ اَصْبَحَ لا يَهْتَمُّ بِاُمُورِ الْمُسلمِينَ فَلَيْسَ مِنْهُمْ، وَ مَنْ سَمِعَ رَجُلاً يُنادى يا لَلْمُسلمِينَ فَلَمْ يُجِبْهُ فَلَيْسَ بِمُسْلِمٍ. حديث","fa":"حضرت محمد صلی الله علیه و آله فرمود: هرکس صبح کند، در حالی که به کارهای مسلمانان اهمیّتی نمی دهد (و به فکر مسلمین نیست)، او از آنان نیست. و هرکس بشنود که کسی مسلمانان را به کمک فرا می خواند ولی پاسخش ندهد، مسلمان نیست.","at":"پیامبر اکرم (ص) — چهل حدیث «گهرهای نبوی» (حدیث ۱۰۷)"},{"id":"d027","by":"prophet","ar":"الراوي: اِنَّ رَسُولَ اللّهِ صلي الله عليه و آله بَعَثَ بِسَريّةٍ فَلَمّا رَجَعُوا قالَ: مَرْحَبا بِقَوْمٍ قَضَوْا الجِهادَ الأصْغَرَ وَ بَقِىَ لَهُمُ الْجِهادُ الأكْبَرُ. قيلَ: يا رَسُولَ اللّه ! وَ مَا الجِهادُ الأكْبَرُ؟ قالَ: جِهادُ النَّفْسِ. حديث","fa":"راوی رسول خدا صلی الله علیه و آله گروهی را در پی یک مأموریت نظامی (سَریّه) فرستاد. چون بازگشتند، فرمود: درود بر گروهی که «جهاد کوچک» را انجام دادند و جهاد بزرگتر برای آنان باقی مانده است. گفتند: ای رسول خدا، جهاد بزرگتر چیست؟ فرمود: جهاد با نفس.","at":"پیامبر اکرم (ص) — چهل حدیث «گهرهای نبوی» (حدیث ۱۰۸)","tip":"نفس امّاره دشمن درونی است و جهاد با آن دشوارتر است. قهرمان کسی است که در این جبهه، فاتح باشد."},{"id":"d028","by":"prophet","ar":"اَلْجَليسُ الصّالِحُ خَيرٌ مِنَ الوَحْدَةِ وَ الْوَحْدَةُ خَيرٌ مِنْ جَليسِ السُّوءِ وَ اِمْلاءُ الْخَيْرِ خَيْرٌ مِنَ السُّكُوتِ وَ السُّكُوتُ خيرٌ مِنْ اِمْلاءِ الشَّرِّ. حديث","fa":"پیامبر اکرم صلی الله علیه و آله فرمود: همنشین شایسته و خوب، بهتر از تنهایی است و تنهایی بهتر از همنشین بد است. یاد دادن نیکی بهتر از سکوت است و سکوت، بهتر از یاد دادن بدی است.","at":"پیامبر اکرم (ص) — چهل حدیث «گهرهای نبوی» (حدیث ۱۰۹)"},{"id":"d029","by":"prophet","ar":"مَنْ ماتَ وَ لَيْسَ لَهُ اِمامٌ يَسْمَعُ لَهُ وَ يُطيعُ، ماتَ مِيتَةً جاهِلِيَّةً. حديث","fa":"پیامبر خدا صلی الله علیه و آله فرمود: هر کس از دنیا برود، در حالی که او را امام و پیشوایی نباشد که مطیع و گوش به فرمان او باشد، به مرگ جاهلیّت مرده است.","at":"پیامبر اکرم (ص) — چهل حدیث «گهرهای نبوی» (حدیث ۱۱۰)","tip":"در عصر غیبت هم تبعیت از «ولایت و رهبری»، نشانه زندگی مکتبی است."},{"id":"d030","by":"prophet","ar":"اِنَّ الرّياسَةَ لا تَصْلَحُ اِلاّ لِأهْلِها، فَمَنْ دَعاالنّاسَ اِلى نَفْسِهِ وَفيهِمْ مَنْ هُوَ اَعْلَمُ مِنْهُ لَمْ يَنْظُرِاللّهُ اِلَيْهِ يَوْمَ القيامَةِ. حديث","fa":"رسول خدا صلی الله علیه و آله فرمود: ریاست، جز برای اهلش، شایسته و روا نیست. پس هرکس مردم را به سوی خود بخواند، در حالی که میان مردم داناتر از او هست، خداوند در روز قیامت به او نگاه نخواهد کرد.","at":"پیامبر اکرم (ص) — چهل حدیث «گهرهای نبوی» (حدیث ۱۱۱)","tip":"در سپردن مسؤولیت های اجتماعی، اولویّت دادن به معیارها و ملاکها و شایستگیها، نه اشخاص و رابطه ها!"},{"id":"d031","by":"prophet","ar":"لِلْمُؤمِنِ عَلَى الْمُؤمِنِ سَبْعَةُ حُقُوقٍ واجِبَةٍ مِنَ اللّهِ عَزَّوَجَلَّ عَلَيه: اَلِأجْلالُ فى عَيْنِهِ، وَ الْوُدُّ لَهُ فى صَدْرِهِ، وَ المُواساةُ لَهُ فى مالِهِ، وَ اَنْ يُحَرِّمَ غَيْبَتَهُ وَ اَنْ يَعُودَهُ فى مَرَضِهِ، وَ اَنْ يُشَيِّعَ جِنازَتَهُ وَ اَنْ لايَقُولَ فيهِ بَعْدَ مَوْتِهِ اِلاّ خَيْرا. حديث","fa":"پیامبر اکرم صلی الله علیه و آله فرمود: مؤمن برگردن برادر مؤمنش هفت حقّ واجب دارد که از سوی خدا بر او واجب شده است: ۱ در چشمش به دیده احترام به او بنگرد. ۲ در دلش محبّت او را داشته باشد. ۳ در مالش او را هم شریک سازد. ۴ غیبت او را حرام بشمارد. ۵ هنگام بیماری از او عیادت کند. ۶ جنازه اش را تشییع کند. ۷ پس ازمرگش، جز خیروخوبی درباره او نگوید.","at":"پیامبر اکرم (ص) — چهل حدیث «گهرهای نبوی» (حدیث ۱۱۲)"},{"id":"d032","by":"prophet","ar":"اَحْسَنُ الهَدْىِ هَدْىُ الأنْبياءِ، وَ اَشْرَفُ الْقَتْلِ قَتْلُ الشُّهَداء. وَ اَعْمَى الْعَمى الضَّلالَةُ بَعْدَ الْهُدى، وَ خَيْرُ الأَعْمالِ ما نَفَعَ، وَ خَيْرُالْهُدى مَااتُّبِعَ، وَ شَرُّ الْعَمى عَمَى القَلْبِ. حديث","fa":"پیامبر اکرم صلی الله علیه و آله فرمود: بهترین روش و سلوک، راه و روش پیامبران است، برترین مرگ، کشته شدنِ شهیدانِ است، بدترین و کورترین کوری، گمراهی پس از هدایت است، بهترین کارها آن است که سودمند باشد، بهترین هدایت، آن است که مورد پیروی قرار گیرد و بدترین کوری، کوریِ دل است.","at":"پیامبر اکرم (ص) — چهل حدیث «گهرهای نبوی» (حدیث ۱۱۳)"},{"id":"d033","by":"prophet","ar":"اَلاَ اُخْبِرُكُمْ بِاَشرارِكُمْ؟ قالُوا: بَلى يارَسُولَ اللّهِ صلي الله عليه و آله. قالَ صلي الله عليه و آله: اَلْمَشّاؤُونَ بِالَّنميمَةِ، اَلْمُفَرِّقُونَ بَيْنَ الأَحِبَّةِ، اَلباغُونَ لِلْبَراءِ الْعَيْبَ. حديث","fa":"رسول خدا صلی الله علیه و آله به اصحاب خویش فرمود: آیا به شما خبر دهم که بدترین شما کیست؟ گفتند: آری ای رسول خدا. فرمود: سخن چینان، آنان که میان دوستان تفرقه ایجاد می کنند، و آنان که برای افراد بی گناه، در پی عیب هستند.","at":"پیامبر اکرم (ص) — چهل حدیث «گهرهای نبوی» (حدیث ۱۱۴)"},{"id":"d034","by":"prophet","ar":"ثَمانِيةٌ اِنْ اُهينُوا فَلا يَلُومُوا اِلاّ اَنْفُسَهُمْ: اَلذّاهِبُ اِلى مائِدَةٍ لَمْ يُدْعَ اِلَيْها، وَ الْمُتأمِّرُ عَلى رَبِّ الْبَيْتِ، وَطالِبُ الْخَيْرِ مِنْ اَعْدائِهِ، وَ طالِبُ الْفَضْلِ مِنَ اللِّئامِ، وَ الدّاخِلُ بَيْنَ اَثْنِيْنِ فى سرٍّ لَمْ يُدْخِلاهُ فيهِ، وَالْمُسْتَخِفُّ بِالسُّلطانِ، وَالجالِسُ فىمَجْلِسٍ لَيْسَ لَهُ بِاَهْلٍ وَالْمُقْبِلُ بِالْحَديثِ عَلى مَنْ لايَسْمَعُ مِنْهُ. حديث","fa":"رسول خدا صلی الله علیه و آله فرمود: هشت نفرند که اگر مورد اهانت قرار گرفتند، جز خودشان کس دیگری را سرزنش نکنند: ۱ کسی که به مهمانی و سفره ای رود که دعوت نشده است. ۲ مهانی که به صاحب خانه دستور دهد. ۳ کسی که از دشمنانش خیر و نیکی بطلبد. ۴ کسی که از فرومایگان انتظار فضل و نیکی داشته باشد. ۵ کسی که در یک کار سرّی میان دو نفر وارد شود که او را وارد آن راز نکرده اند. ۶ کسی که حکومت را سبک بشمارد. ۷ کسی که جایی نشیند که شایسته آنجا نیست. ۸ کسی که سخن خود را به کسی بگوید که از او حرف شنوایی ندارد.","at":"پیامبر اکرم (ص) — چهل حدیث «گهرهای نبوی» (حدیث ۱۱۵)"},{"id":"d035","by":"prophet","ar":"اَلا اَدُلُّكُمْ عَلى خَيْرِ اَخْلاقِ الدُّنيا وَ الآخِرَةِ؟ تَصِلُ مَنْ قَطَعَكَ وَ تُعْطى مَنْ حَرَمَكَ وَتَعْفُو عَمَّنْ ظَلَمَكَ. حديث","fa":"رسول اکرم صلی الله علیه و آله فرمود: آیا شما را به بهترین اخلاق دنیا و آخرت راهنمایی کنم؟ آن است که با هرکس که از توگسسته است، بپیوندی به هر کس که تو را محروم کرده، عطا کنی و هر کس را که به تو ستم کرده است، عفو کنی.","at":"پیامبر اکرم (ص) — چهل حدیث «گهرهای نبوی» (حدیث ۱۱۶)"},{"id":"d036","by":"prophet","ar":"بِاْلعِلْمِ يُطاعُ اللّهُ وَ يُعْبَدُ، وَبِاْلعِلْمِ يُعْرَفُ اللّهُ وَيُوَحَّدُ، وَ بِهِ تُوصَلُ الأرْحامُ و تُعْرَفُ الحَلالُ وَالْحَرامُ وَ العِلْمُ اَمامَ الْعَقْلِ. حديث","fa":"حضرت محمد صلی الله علیه و آله فرمود: به وسیله علم، خداوند اطاعت و پرستیده می شود، به وسیله علم، خداوند شناخه می شود و یکتا شمرده می گردد، به وسیله علم، صله رحِم می شود و حلال و حرام شناخته می شود، و علم، جلودار عقل است.","at":"پیامبر اکرم (ص) — چهل حدیث «گهرهای نبوی» (حدیث ۱۱۷)"},{"id":"d037","by":"prophet","ar":"اُوصيكَ بِتَقْوَى اللّهِ وَصِدْقِ الْحَديثِ وَالْوَفاءِ بالْعَهْدِ وَاَداءِ الأمانَةِ وَتَرْكِ الخِيانَةِ وَ لينِ الْكَلامِ وَ بَذْلِ السَّلامِ وَ حِفْظِ الجارِ وَرَحْمَةِ الْيَتيمِ وَحُسْنِ الْعَمَلِ وَقَصْرِ الأَمَلِ. حديث","fa":"حضرت رسول صلی الله علیه و آله فرمود: تو را سفارش می کنم به تقوای خدا، راستگویی، وفای به عهد، امانت داری، ترک خیانت، نرمش در گفتار، بذل سلام، حفظ همسایه، مهربانی با یتیم، نیکوکاری و کوتاه ساختن آرزو.","at":"پیامبر اکرم (ص) — چهل حدیث «گهرهای نبوی» (حدیث ۱۱۸)"},{"id":"d038","by":"prophet","ar":"ثَلاثٌ مَنْ لَمْ يَكُنْ فَيهِ لَمْ يَقُمْ لَهُ عَمَلٌ: وَرَعٌ يَحْجُزُهُ عَنْ مَعاصِى اللّهِ عَزَّوَجَلَّ، وَ عِلمٌ يَرُدُّ بِهِ جَهْلَ السَّفيهِ، وَ عَقلٌ يُدارى بِهِ النّاسَ. حديث","fa":"رسول خدا صلی الله علیه و آله فرمود: سه چیز است که در هرکس نباشد، هیچ کار او استواری و قوام نیابد: ۱ پرهیزکاری و ورعی که او را از معصیتهای خدای متعال نگه دارد، ۲ دانشی که به وسیله آن، نادانیِ سفیه را برگرداند، ۳ و عقل و خردی که به وسیله آن با مردم مدارا کند.","at":"پیامبر اکرم (ص) — چهل حدیث «گهرهای نبوی» (حدیث ۱۱۹)"},{"id":"d039","by":"prophet","ar":"اِغْتَنِمْ خَمْسا قَبْلَ خَمْسٍ: شَبابَكَ قَبْلَ هِرَمِكَ، وَ صِحَّتَكَ قَبْلَ سُقْمِكَ، وَ غِناكَ قَبْلَ فَقْرِكَ، وَفَراغَكَ قَبْلَ شُغْلِكَ، وَ حَياتَكَ قَبْلَ مَوْتِكَ. حديث","fa":"پیامبر خدا صلی الله علیه و آله فرمود: پنج چیز را قبل از پنج چیز، غنیمت شمار، ۱ جوانی ات را قبل از پیری ات، ۲ تندرستی ات را قبل از بیماری ات، ۳ توانگری ات را قبل از تهیدستی ات، ۴ آسودگی ات را قبل از گرفتاری ات، ۵ زندگی ات را قبل از مرگت.","at":"پیامبر اکرم (ص) — چهل حدیث «گهرهای نبوی» (حدیث ۱۲۰)","tip":"بهره وری از «داشته ها» در مسیر معنویت و هدف و شناخت نعمتهای الهی."},{"id":"d040","by":"ali","ar":"أَلْحَمْدُ لِلّهِ الَّذى لا تَدْرِكُهُ الشَّواهِدُ وَ لاَ تَحْويهِ الْمَشاهِدُ وَ لا تَراهُ النَّواظِرُ وَ لا تَحْجُبُهُ السَّواتِرُ. الدّالُ عَلىَ قِدَمِهِ بِحُدُوثِ خَلْقِهِ وَ بِحُدُوثِ خَلْقِهِ عَلى وُجُودِهِ وَ بِاشْتِباهِهِمْ عَلى أَنْ لاشَبَهَ لَهُ. حديث","fa":"حضرت علی علیه السلام فرمود: سپاس خداوندی را که تجربه ها او را دریافت نمی کند و در هیچ عرصه ای نمی گنجد، چشمها او را نمی بینند و پرده ها او را نمی پوشند. با آفرینش پدیدارها برقدیم بودن خود دلیل آورد و پدیده ها را دلیل هستی خود ساخت و همانندی آنها را گواه بی همانندی خود آورد.","at":"امام علی (ع) — چهل حدیث «گهرهای علوی» (حدیث ۲۰۱)"},{"id":"d041","by":"ali","ar":"فَانْظُرْ إِلَى الشَّمْسِ وَالْقَمَرِ، وَالنَّبَاتِ وَالشَّجَرِ، وَالْمَاءِ وَالْحَجَرِ، وَاخْتِلاَفِ هذَا اللَّيْلِ وَالنَّهَارِ، وَتَفَجُّرِ هذِهِ الْبِحَارِ، وَكَثْرَةِ هذِهِ الْجِبَالِ، وَطُولِ هذِهِ الْقِلاَلِ. وَتَفَرُّقِ هذِهِ اللُّغَاتِ، وَالْأَلْسُنِ الُْمخْتَلِفَاتِ.فَالْوَيْلُ لِمَنْ أَنْكَرَ الْمُقَدِّرَ، وَجَحَدَ الْمُدَبِّرَ! زَعَمُوا أَنَّهُمْ كَالنَّبَاتِ مَا لَهُمْ زَارِعٌ، وَلاَ لاِخْتِلاَفِ صُوَرِهِمْ صَانِعٌ؛ وَلَمْ يَلْجَؤُوا إِلَى حُجَّةٍ فِيها ادَّعَوْا، وَلاَ تَحْقِيقٍ لِمَا أَوْعَوْا. وَهَلْ يَكُونُ بِنَاءٌ مِنْ غَيْرِ بَانٍ، أَوْ جِنَايَةٌ مِنْ غَيْرِ جَانٍ! حديث","fa":"حضرت علی علیه السلام فرمود: خورشید و ماه وگیاه و درخت و آب و سنگ را بادقت بنگر، و نیز آمد و شد شب و روز را و درهم خروشیدن دریاها و انبوهی کوهها و بلندای قله ها را و نیز کثرث واژگان و گوناگونی زبانها را در نظر آر.با این همه، وای بر آنان که تقدیر گر آفرینش را انکار می کنند و مدبر نظام هستی را نادیده می گیرند. اینان می پندارند چون علفهای هرز، کشاورزی ندارند و چهره های گونه گون آنان را نگارگری نیست، بی آنکه برای پندار خود به دلیل و برهانی تکیه کنند و برای جنجال بیهوده شان پشتوانه تحقیق و پژوهشی داشته باشند.","at":"امام علی (ع) — چهل حدیث «گهرهای علوی» (حدیث ۲۰۲)"},{"id":"d042","by":"ali","ar":"فَبَعَثَ فِيهِمْ رُسُلَهُ، وَواتَرَ إِلَيْهِمْ أَنْبِياءَهُ،لِيَسْتَأْدُوهُمْ مِيثاقَ فِطْرَتِهِ،وَيُذَكِّرُوهُمْ مَنْسِىَّ نِعْمَتِهِ،وَيَحْتَجُّوا عَلَيْهِمْ بِالتَّبْلِيغِ،وَيُثِيرُوا لَهُمْ دَفائِنَ الْعُقُولِ،وَيُرُوهُمْ آياتِ الْمَقْدِرَةِ.حديث","fa":"حضرت علی علیه السلام فرمود: چنین بود که خداوند فرستادگانش را در میان آنان مردم برانگیخت و پیامبران خود را پی در پی به سوی آنها گسیل داشت تا: پایبندی به میثاق فطرت الهی را از آنان مطالبه کنند، و نعمتهای از یاد رفته خداوندی را به یادشان آوردند، و با ابلاغ رسالت الهی حجت را بر آنان تمام کنند، و گنجینه های پنهانِ خِردها را بر آشوبند و شکوفا کنند، و آیات قدرت و حکمت الهی را بر آنان بنمایانند.","at":"امام علی (ع) — چهل حدیث «گهرهای علوی» (حدیث ۲۰۳)"},{"id":"d043","by":"ali","ar":"وَأَشْهَدُ أَنَّ مُحَمَّدا عَبْدُهُ وَرَسُولُهُ، أَرْسَلَهُ بِالدِّينِ الْمَشْهُورِ، وَالْعَلَمِ الْمَأْثُورِ، وَالْكِتابِ الْمَسْطُورِ، وَالنُّورِالسَّاطِعِ، وَالضِّياءِ اللاَّمِعِ، وَالأَمْرِ الصَّادِعِ، إزاحَةً لِلشُّبُهاتِ، وَاحْتِجاجا بِالبَيِّناتِ، وَتَحْذِيرا بِالاْياتِ، وَتَخْوِيفا بِالْمَثُلاَتِ. حديث","fa":"حضرت علی علیه السلام فرمود: گواهی می دهم که محمد صلی الله علیه و آله بنده و فرستاده خداوند است که او را با آئینی پر آوازه و پرچمی برافراشته و کتابی نگاشته و فروغی درخشان و شعاعی تابان و فرمانی قاطع و برّان، گسیل داشت. تا شبهه ها را بزداید و با حقایق روشنگر برهان آورد و با آیات الهی هشدار دهد و با یاد آوری سنّت های تاریخ مردم را بیم دهد.","at":"امام علی (ع) — چهل حدیث «گهرهای علوی» (حدیث ۲۰۴)"},{"id":"d044","by":"ali","ar":"انْظُرُوا أَهْلَ بَيْتِ نَبِيِّكُمْفَالْزَمُوا سَمْتَهُمْ، وَاتَّبِعُوا أَثَرَهُمْ،فَلَنْ يُخْرِجُوكُمْ مِنْ هُدًى، وَلَنْ يُعيدُوكُمْ فِيرَدًى،فَإِنْ لَبَدُوا فَالْبُدُوا، وَإِنْ نَهَضُوا فَانْهَضُوا.وَلاَ تَسْبِقُوهُمْ فَتَضِلُّوا، وَلاَ تَتَأَخَّرُوا عَنْهُمْ فَتَهْلِكُوا. حديث","fa":"حضرت علی علیه السلام فرمود: خاندان پیامبرتان را به دقت بنگرید و خود را به همسویی با آنان ملزم کنید و گام به گام از آنان پیروی کنید، زیرا که آنان هرگز از راه هدایت بیرونتان نمی کنند و دیگر بار به پرتگاه جاهلیت شما را نمی افکنند. پس اگر نشستند، همراه آنان بنشینید و اگر برخاستند با نهضتشان هماهنگ شوید، نه بر آنان پیشی گیرید که به گمراهی درافتید و نه از آنان واپس مانید که هلاک شوید.","at":"امام علی (ع) — چهل حدیث «گهرهای علوی» (حدیث ۲۰۵)"},{"id":"d045","by":"ali","ar":"وَاعْلَمُوا أَنَّ هذاالْقُرْآنَ هُوَ النَّاصِحُ الَّذِي لاَيَغُشُّ، وَالْهادِيالَّذِيلاَيُضِلُّ، وَالُْمحَدِّثُ الَّذِيلاَيَكْذِبُ. وَما جالَسَ هذَا الْقُرْآنَ أَحَدٌ إِلاَّ قامَ عَنْهُ بِزِيادَةٍ أَوْ نُقْصانٍ: زِيادَةٍ فِيهُدًى، أَوْ نُقْصانٍ مِنْ عَمًى. حديث","fa":"حضرت علی علیه السلام فرمود: و نیز بدانید این قرآن تنها ناصحی است که نصیحت خود را به خیانت نمی آلاید، و تنها هدایتگری است که هرگز بگمراهی نمی کشاند و تنها سخنگویی است که هیچگاه دروغ نمی گوید. کسی با قرآن هم نشین نشد مگر اینکه با فزونی و کاستی برخاست، فزونی هدایت و کاستی در کور دلی و ناآگاهی.","at":"امام علی (ع) — چهل حدیث «گهرهای علوی» (حدیث ۲۰۶)"},{"id":"d046","by":"ali","ar":"إِنَّ أَمْرَنا صَعْبٌ مُسْتَصْعَبٌ،لاَ يَحْتَمِلُهُ إِلاَّ عَبْدٌ امْتَحَنَ اللّهُ قَلْبَهُ لِلاْءِيمانِ،وَلاَ يَعْي حَدِيثَنا إِلاَّ صُدُورٌ أَمِينَةٌ، وَأَحْلاَمٌ رَزِينَةٌ. حديث","fa":"حضرت علی علیه السلام فرمود: تبعیت و همراهی با ما و پیام و امر ما دشوار و پیچیده است، بر دوش کشیدن این بار سنگین را کسی نتواند مگر آن بنده ای که خداوند قلب او را برای ایمان آزموده باشد. چه اینکه جز سینه های امانتدار و اندیشه های استوار، ژرفای گفتار و حدیث ما را در نیابند.","at":"امام علی (ع) — چهل حدیث «گهرهای علوی» (حدیث ۲۰۷)"},{"id":"d047","by":"ali","ar":"إِنَّ الدُّنْيا دارُ صِدْقٍ لِمَنْ صَدَقَها،وَدارُ عافِيَةٍ لِمَنْ فَهِمَ عَنْها،وَدارُ غِنًى لِمَنْ تَزَوَّدَ مِنْها،وَدارُ مَوْعِظَةٍ لِمَنِ اتَّعَظَ بِها.مَسْجِدُ أَحِبَّاءِ اللّهِ،وَمُصَلَّى مَلاَئِكَةِ اللّهِ،وَمَهْبِطُ وَحْيِ اللّهِ،وَمَتْجَرُ أَوْلِياءِ اللّهِ. حديث","fa":"حضرت علی علیه السلام فرمود: بی گمان دنیا برای راستان سرای راستیو برای دنیاشناسان سرای عافیتو برای توشه گیران سرای بی نیازیو برای پند پذیران سرای پند و اندرز است.دنیا مسجد دوستان خداو نمازخانه فرشتگان اوو جایگاه فرود وحیو بازار اولیاء خداوند است.","at":"امام علی (ع) — چهل حدیث «گهرهای علوی» (حدیث ۲۰۸)"},{"id":"d048","by":"ali","ar":"وَإِنَّمَا الدُّنْيَا مُنْتَهَى بَصَرِ الْأَعْمَى،لاَ يُبْصِرُ مِمَّا وَراءَها شَيْئا،وَالْبَصِيرُ يَنْفُذُها بَصَرُهُ،وَيَعْلَمُ أَنَّ الدَّارَ وَراءَها.فَالْبَصِيرُ مِنْها شاخِصٌ، وَالْأَعْمَى إِلَيْها شاخِصٌ.وَالْبَصِيرُ مِنْها مُتَزَوِّدٌ، وَالْأَعْمَى لَها مُتَزَوِّدٌ. حديث","fa":"حضرت علی علیه السلام فرمود: دنیا، نگاه کور دلان را بن بستی است که فراسویش هیچ نمی بینند، و چشمان دارای بصیرت از دنیاگذشته، سرای هستی را در آن سوی دنیا می یابد.چنین است که بینایان از دنیا و با توشه ای که از آن گرفته اند رخت سفر می بندند و کوردلان به دنیا چشم دوخته اند، اهل بینش از دنیا و کور دل برای دنیا توشه می گیرد.","at":"امام علی (ع) — چهل حدیث «گهرهای علوی» (حدیث ۲۰۹)"},{"id":"d049","by":"ali","ar":"فَإِنَّ الدُّنْيا أَدْبَرَتْ، وَآذَنَتْ بِوَدَاعٍ،وَإِنَّ الاْخِرَةَ قَدْ أَقْبَلَتْ وَأَشْرَفَتْ بِاطِّلاَعٍ،أَلاَ وَإِنَّ الْيَوْمَ المِضْمَارَ، وَغَدا السِّبَاقَ،وَالسَّبَقَةُ الْجَنَّةُ، وَالْغايَةُ النّارُ. حديث","fa":"حضرت علی علیه السلام فرمود: اینک دنیا روی گردانده است و وداع می کند و آخرت روی آورده است و طلایه های آن نمایان شده است. هشدار! که امروز زمان تمرین و آزمایش است و فردا هنگام مسابقه، مسابقه ای که بردش بهشت است و باخت آن، آتش.","at":"امام علی (ع) — چهل حدیث «گهرهای علوی» (حدیث ۲۱۰)"},{"id":"d050","by":"ali","ar":"مَنِ اْستَحْكَمَتْ لى فيهِ خَصْلَةٌ مِنْ خِصالِ الْخَيْرِ،إحْتَمَلْتُهُ عَلَيْها وَ اغْتَفَرْتُ فَقْدَ ما سِواها،وَ لا أَغْتَفِرُ فَقْدَ عَقْلٍ وَلا دِينٍ،لاَِنَّ مُفارَقَةَ الدّينِ مُفارَقَةِ الْأَمْنِ،فَلا يَتَهَنَّأُ بَحَياةٍ مَعَ مَخافَةٍ،وَ فَقْدُ الْعَقْلِ فَقْدُ الْحَياةِ وَ لا يُقاسُ إِلاّ بِالْأَمْواتِ. حديث","fa":"حضرت علی علیه السلام فرمود: هر که خصلتی از خصال نیک را به کار بندد و آن را در خود ملکه نماید او را با همان عادت پسندیده می پذیرم و از اتصاف به خصلت های نیک دیگر چشم می پوشم، اما هیچگاه نداشتن عقل و دین را نمی بخشم، زیرا نداشتن دین یعنی نداشتن امنیت و آسایش، و زندگی در سایه ترس و نگرانی گوارا نیست.چه اینکه نداشتن عقل بمعنای نداشتن خود زندگی است و حیات بدون عقل تنها به زندگی مردگان می ماند.","at":"امام علی (ع) — چهل حدیث «گهرهای علوی» (حدیث ۲۱۱)"},{"id":"d051","by":"ali","ar":"شَيئانِ هُما مِلاكُ الدّينِ:أَلصِّدْقُ وَ الْيَقينُ. حديث","fa":"حضرت علی علیه السلام فرمود: ملاک و میزان دینداریراستی و باور آگاهانه یقین است.","at":"امام علی (ع) — چهل حدیث «گهرهای علوی» (حدیث ۲۱۲)"},{"id":"d052","by":"ali","ar":"إِنَّ قَوْما عَبَدُوا اللّهَ رَغْبَةً فَتِلْكَ عِبادَةُ التُّجَّارِ،وَإِنَّ قَوْما عَبَدُوا اللّهَ رَهْبَةً فَتِلْكَ عِبَادَةُ الْعَبِيدِ،وَإِنَّ قَوْما عَبَدُوا اللّهَ شُكْرا فَتِلْكَ عِبَادَةُ الْأَحْرَارِ. حديث","fa":"حضرت علی علیه السلام فرمود: گروهی خداوند را به سودای ثواب و پاداش بندگی می کنند، که نیایشی سودا گرانه است و گروهی دیگر از ترس کیفر و عذاب تن به بندگی می دهند، که بندگی بردگان است و گروهی دیگر خدای را به انگیزه سپاس و ستایش می پرستند و این عبادت آزادگان است.","at":"امام علی (ع) — چهل حدیث «گهرهای علوی» (حدیث ۲۱۳)"},{"id":"d053","by":"ali","ar":"عِبادَاللّهِ، إِنَّ مِنْ أَحَبِّ عِبادِاللّهِ إِلَيْهِ عَبْدا أَعانَهُ اللّهُ عَلَى نَفْسِهِ، فَاسْتَشْعَرَ الْحُزْنَ، وَتَجَلْبَبَ الْخَوْفَ... وَصارَ مِنْ مَفاتيحِ أَبْوابِ الْهُدَى، وَمَغالِيقِ أَبْوابِ الرَّدَى... قَدْ أَمْكَنَ الْكِتابَ مِنْ زِمامِهِ، فَهُوَ قائِدُهُ وَإِمامُهُ، يَحُلُّ حَيْثُ حَلَّ ثَقَلُهُ، وَيَنْزِلُ حَيْثُ كانَ مَنْزِلُهُ. حديث","fa":"حضرت علی علیه السلام فرمود: ای بندگان خدا بی گمان محبوب ترین بندگان در پیشگاه خداوند، کسی است که خدا او را در نبرد با نفس خویش یاری کرده است.او حزن دوری از خدای خود را جامه زیرین و ترس از عذاب او را جامه زبرین خود نموده و... خود به تنهایی کلید همه درهای هدایت و قفل همه درهای هلاکت و سقوط گردیده است.قرآن را رهبر و پیشوای خود قرار داده و زمام خود را به او سپرده است، هر جا که قرآن منزل کند او نیز فرود آید و هر جا که قرآن، برگزیند او نیز منزل کند.","at":"امام علی (ع) — چهل حدیث «گهرهای علوی» (حدیث ۲۱۴)"},{"id":"d054","by":"ali","ar":"الْمُؤْمِنُ بِشْرُهُ فِي وَجْهِهِ، وَحُزْنُهُ فِي قَلْبِهِ،أَوْسَعُ شَيْءٍ صَدْرا، وَأَذَلُّ شَيْءٍ نَفْسا.يَكْرَهُ الرِّفْعَةَ، وَيَشْنَأُ السُّمْعَةَ.طَوِيلٌ غَمُّهُ، بَعِيدٌ هَمُّهُ،كَثِيرٌ صَمْتُهُ، مَشْغُولٌ وَقْتُهُ.شَكُورٌ صَبُورٌ، مَغْمُورٌ بِفِكْرَتِهِ، ضَنِينٌ بِخَلَّتِهِ،سَهْلُ الْخَلِيقَةِ، لَيِّنُ الْعَرِيكَةِ!نَفْسُهُ أَصْلَبُ مِنَ الصَّلْدِ، وَهُوَ أَذَلُّ مِنَ الْعَبْدِ. حديث","fa":"حضرت علی علیه السلام فرمود: چهره مؤمن شاد و دل او گریان است، گستره سینه او از هر پهنه ای وسیع تر و خود او از همه متواضع تر است، برتری را خوش ندارد و آوازه و اشتهار را زشت می شمرد، غمش طولانی و اندوهش ژرف و سکوتش بسیار و وقتش مشغول به کار است.پرسپاس و پرشکیب و فرورفته در اندیشه است و نسبت به اظهار گرفتاری های خود برای دیگران بخل می ورزد، نرمخو و انعطاف پذیر است و با آنکه جانی با صلابت تر از سنگ خارا دارد در رفتارش از بندگان نیز خاکسارتر است.","at":"امام علی (ع) — چهل حدیث «گهرهای علوی» (حدیث ۲۱۵)"},{"id":"d055","by":"ali","ar":"اعْقِلُوا الْخَبَرَ إِذا سَمِعْتُمُوهُعَقْلَ رِعايَةٍ لاَ عَقْلَ رِوايَةٍ،فَإِنَّ رُوَاةَ الْعِلْمِ كَثِيرٌ، وَرُعَاتَهُ قَلِيلٌ. حديث","fa":"حضرت علی علیه السلام فرمود: چون خبری را شنیدید همانند ژرف اندیشان و نه چون ظاهر بینان ژرف در آن بیندیشید و تنها به شنیده خود بسنده نکنید زیرا که روایت گران دانش بسیارند و رعایت کنندگانش اندک.","at":"امام علی (ع) — چهل حدیث «گهرهای علوی» (حدیث ۲۱۶)"},{"id":"d056","by":"ali","ar":"الْفَقِيهُ كُلُّ الْفَقِيهِ مَنْ لَمْ يُقَنِّطِ النَّاسَ مِنْ رَحْمَهِ اللّهِ،وَلَمْ يُؤْيِسْهُمْ مِنْ رَوْحِ اللّهِ، وَلَمْ يُؤْمِنْهُمْ مِنْ مَكْرِاللّهِ. حديث","fa":"حضرت علی علیه السلام فرمود: فقیه کامل کسی است که نه مردم را از رحمت خداوند دلسرد کند و نه از مهر و لطفش نومید سازد و نه از مکر خداوندی ایمنشان سازد.","at":"امام علی (ع) — چهل حدیث «گهرهای علوی» (حدیث ۲۱۷)"},{"id":"d057","by":"ali","ar":"عِبادَ اللّهِ! زِنُوا أَنْفُسَكُمْ مِنْ قَبْلِ أَنْ تُوزَنُوا،وَحاسِبُوها مِنْ قَبْلِ أَنْ تُحاسَبُوا،وَتَنَفَّسُوا قَبْلَ ضِيقِ الْخِناقِ،وَانْقادُوا قَبْلَ عُنْفِ السِّياقِ. حديث","fa":"حضرت علی علیه السلام فرمود: ای بندگان خدا! پیش از آنکه سنجیده شوید خویشتن را بسنجید و پیش از آنکه به حسابتان رسیدگی شود حساب خود را تسویه کنید، پیش از آنکه گلویتان بسته شود و نفس به شماره افتد تنفس کنید و قبل از آنکه شما را به زور برانند خود، به راه افتید.","at":"امام علی (ع) — چهل حدیث «گهرهای علوی» (حدیث ۲۱۸)"},{"id":"d058","by":"ali","ar":"قُرِنَتِ الْهَيْبَةُ بِالْخَيْبَةِ، وَالْحَياءُ بِالْحِرْمانِ،وَالْفُرْصَةُ تَمُرُّ مَرَّ السَّحابِ، فَانْتَهِزُوا فُرَصَ الْخَيْرِ. حديث","fa":"حضرت علی علیه السلام فرمود: هیبت و ترس، قرین ناکامی و شرم و حیاء، زمینه ساز محرومیت است و فرصتها چونان ابر در گذرند پس فرصتهای نیک را دریابید. حدیث","at":"امام علی (ع) — چهل حدیث «گهرهای علوی» (حدیث ۲۱۹)"},{"id":"d059","by":"ali","ar":"فَإِنَّ الْغَايَةَ أَمَامَكُمْ، وَإِنَّ وَرَاءَكُمُ السَّاعَةَ تَحْدُوكُمْ.تَخَفَّفُوا تَلْحَقُوا، فَإِنَّمَا يُنْتَظَرُ بِأَوَّلِكُمْ آخِرُكُمْ. حديث","fa":"حضرت علی علیه السلام فرمود: پایان راه فرا روی شماست و قیامت از پشت سر، شما را به پیش می راند. سبکبار شوید تا به پیشتازان بپیوندید، چرا که اولین های این کاروان، آخرین نفرهایش را انتظار می برد.","at":"امام علی (ع) — چهل حدیث «گهرهای علوی» (حدیث ۲۲۰)"},{"id":"d060","by":"hasan","ar":"قالَ الحَسنُ بنُ عَلِىٍ عليهماالسلام فى قَولِ اللّهِ عَزَّ وَ جَلَّ: «بِسمِ اللّهِ الرَّحمنِ الرِّحيمِ»: فَقالَ: اللّهُ هُوَ الَّذِي يَتَأَلَّهُ إِلَيْهِ عِنْدَ الْحَوائِجِ وَالشَّدائِدِ كُلُّ مَخْلُوقٍ عِنْدَ اِنْقِطاعِ الرَّجاءِ مِنْ كُلِّ مَنْ دُونَهُ وَتُقَطَّعُ الأسْبابَ مِنْ جَميعِ مَنْ سِواهُ تَقُولُ بِسْمِ اللّهِ أَيْ أَسْتَعينُ عَلى أُمُورِي كُلِّها بِاللّهِ الَّذِي لا تُحِقُّ الْعِبادَةُ إلاّ لَهُ، المُغيثُ إذا اسْتُغيثَ وَالُمجيبُ إذا دُعِى. حديث","fa":"امام مجتبی علیه السلام با تفسیر «بسمله»حدیث راه فطرت (که یکی از قوی ترین برهانهای خداشناسی است) را بیان می کند، آن حضرت فرمود: «خداوند متعال وجودی است که همه موجودات در نیازمندی و سختیها به او پناه می برند، به ویژه هنگامی که امید از غیر او قطع گردد و همه وسائط و اسباب را ناچیز ببیند. [یعنی فطرت خداشناسی، انسان را در تنگناها به سوی واجب الوجود هدایت می کند]این که می گویی: «بسم اللّه..»؛ یعنی یاری و کمک می خواهم در همه کارهایم از خداوندی که عبادت (خضوع و کرنش) برای غیرش سزاوار نیست، او فریادرسی است که به هنگام دادخواهی دستگیری می نماید، و اگر کسی بخواندش پاسخ می گوید.»","at":"امام حسن (ع) — چهل حدیث «گهرهای حسنی» (حدیث ۴۰۱)"},{"id":"d061","by":"hasan","ar":"إنَّ أباذَر يَقُولُ: الفَقْرُ أَحَبُّ إِلَيَّ مِنَ الغِنى وَالسُقْمُ أَحَبُّ إِلَيَّ مِنَ الصِحَّةِ. فَقالَ عليه السلام: رَحِمَ اللّهُ أَباذَرَ، أَمّا أَنَا أَقُولُ: مَنِ اتَّكَلَ عَلى حُسْنِ اِخْتِيارِاللّهِ لَمْ يَتَمَنَّ أَنَّهُ فِي غَيْرِ الْحالَةِ الَّتِي اخْتارَاللّهُ لَهُ، وَهَذا حَدُّ الوُقُوفِ عَلى الرِّضا بِما تَصَرَّفَ بِهِ الْقَضاءُ. حديث","fa":"به امام مجتبی علیه السلام گفته شد، که اباذر ره می گفت: «فقر و تنگدستی را از بی نیازی، و بیماری را از تندرستی و سلامتی بیشتر دوست دارم». حضرت فرمود: خداوند ابوذر را رحمت کند امّا من می گویم: آن کس که بر حسن اختیار خداوند اعتماد کند، چیزی را نمی طلبد که جز خداوند برایش انتخاب کرده باشد. و این است معنای خشنودی در برابر حکم خداوند سبحان.","at":"امام حسن (ع) — چهل حدیث «گهرهای حسنی» (حدیث ۴۰۲)"},{"id":"d062","by":"hasan","ar":"قالَ الحَسنُ بنُ عَلِىٍ عليهماالسلام في وَصفِ القُرآنِ المَجيد: إنَّ هَذَا القُرآنَ فِيهِ مَصابِيحُ النُّورِ، وَشِفاءُ الصُّدُورِ، فَلْيَجُلْ جالٌ بَصَرَهُ وَ يَفْتَحُ لِلْضِّياءِ نَظَرَهُ، فَإِنَّ التَّفْكِيرَ حَياةُ القَلْبِ البَصيرِ، كَما يَمْشِى المُسْتَنِيرُ فِى الظُّلُماتِ بِالنُّورِ. حديث","fa":"امام حسن مجتبی علیه السلام در توصیف و شرح حال قرآن مجید فرمود: «در این قرآن است چراغهای درخشنده هدایت و شفای دلها و قلب ها، پس باید دلها را با فروغ تابناکش روشن ساخت و با گوش فرادادن به فرامینش، قلب را که مرکز فرماندهی بدن است، در اختیارش گذاشت؛ زیرا به وسیله اندیشیدن، قلب، زندگیِ روشن خود را می یابد، همان طوری که رهروان در پرتو نور از تاریکیها گذر می کنند و می رهند.»","at":"امام حسن (ع) — چهل حدیث «گهرهای حسنی» (حدیث ۴۰۳)"},{"id":"d063","by":"hasan","ar":"«ما بَقِىَ فِى الدُّنْيا بَقِيَّةٌ غَيْرَ هَذَا القُرآنِ فَاتَّخِذُوهُ إماما يَدُلُّكُمْ عَلى هُداكُمْ، وَإنَّ أَحَقَ النّاسِ بِالقُرآنِ مَنْ عَمِلَ بِهِ وَإنْ لَمْ يَحْفَظْهُ وَأَبْعَدَهُمْ مِنْهُ مَنْ لَمْ يَعْمَلْ بِهِ وَإنْ كانَ يَقْرَأُهُ.» حديث","fa":"امام حسن مجتبی علیه السلام فرمود: «تنها چیزی که در این دنیای فانی، باقی می ماند قرآن است، پس قرآن را پیشوا و امام خود قرار دهید، تا به راه راست و مستقیم هدایت شوید. همانا نزدیک ترین مردم به قرآن کسانی هستند که بدان عمل کند، گرچه به ظاهر (آیات) آن را حفظ نکرده باشند و دورترین افراد از قرآن کسانی هستند که به دستورات آن عمل نکنند گرچه قاری و خواننده آن باشند.»","at":"امام حسن (ع) — چهل حدیث «گهرهای حسنی» (حدیث ۴۰۴)"},{"id":"d064","by":"hasan","ar":"«إنَّ هذا القُرآنَ يَجِئُ يَوْمَ القِيمَةِ قائِدا وسائِقا يَقُودُ قَوْما إلَى الجَنَّةِ أَحَلُّوا حَلالَهُ وَحَرَّمُوا حَرامَهُ وآمَنُوا بِمُتَشابِهِهِ ويَسُوقُ قَوْما إلَى النّارِ ضَيَّعُوا حُدُودَهُ وأَحْكامَهُ وَاسْتَحَلُّوا حَرامَهُ.» حديث","fa":"امام حسن مجتبی علیه السلام فرمود: «قرآن در صحنه قیامت به صورت رهبر و امام ظهور یافته، مردم را به دو دسته تقسیم می کند: ۱ کسانی که به قرآن عمل نموده، حلال و حرام آن را همانگونه که هست بجا آورده اند و متشابه آن را با قلب پذیرا شده اند، قرآن اینان را به سوی بهشت جاویدان هدایت می نماید. ۲ آنان که حدود و قوانینش را ضایع نمودند و محرّماتش را حلال شمرده و به آن تعدّی کردند، قرآن آنها را به سوی آتش (جهنّم) روانه می سازد.»","at":"امام حسن (ع) — چهل حدیث «گهرهای حسنی» (حدیث ۴۰۵)"},{"id":"d065","by":"hasan","ar":"«أَيُّهَا النّاسُ اِعْقِلُوا عَنْ رَبِّكُمْ، إنَّ اللّهَ عَزَّوَجَلَّ اصْطَفى آدَمَ وَنُوحا وآلَ إبراهيمَ وَآلَ عِمْرانَ عَلَى العالَمينَ، ذُرِّيَةً بَعْضُها مِنْ بَعْضٍ وَاللّهُ سَميعٌ عَليمٌ، فَنَحْنُ الذُرِّيَةُ مِنْ آدَمَ وَالأُسْرَةُ مِنْ نُوحٍ، وَالصَّفْوَةُ مِنْ إبراهيمَ، وَالسُّلالَةُ مِنْ إسماعيلَ وَآلُ مُحَمَّدٍ نحْنُ، فيكُمْ كَالسَماءِ المَرْفُوعَةِ وَالأرْضِ المَدْحُوَّةِ وَالشَّمْسِ الضاحِيَةِ وَكَالشَّجَرَةِ الزَّيْتُونَةِ، لا شَرْقِيَّةٌ وَلا غَربيَّةٌ الَّتى زَيْتُها النَبِيٌّ صلي الله عليه و آله وَعَلِىٌّ فَرْعُها، وَنَحْنُ وَاللّهِ ثَمَرَةُ تِلْكَ الشَّجَرَةِ، فَمَنْ تَعَلَّقَ بِغُصْنٍ مِنْ أَغْصانِها نَجَى وَمَنْ تَخَلَّفَ عَنْها فَإلَى النّارِ هَوى.» حديث","fa":"امام حسن مجتبی علیه السلام فرمود: «ای مردم علم و معرفت را از پروردگار خود بیاموزید. همانا خداوند بزرگ آدم و نوح و آل ابراهیم و آل عمران را برای جهانیان، به پیامبری برگزید، آنان دودمانی بودند که (پاکی، تقوا و فضیلت را) بعضی از بعض دیگر گرفته بودند. خداوند (به کوششهای آنان در راه رسالت) شنوا و داناست. مردم! ما اهل بیت از فرزندان آدم و دودمان نوح و فرزندان برگزیده ابراهیم و تبار اسماعیلیم، ما آل محمد، در میان شما همانند آسمان بلند و همچون زمین گسترده و مثل خورشید پر فروغیم. همانند درخت زیتونیم که نه به شرق مایل است و نه به غرب. درختی که ریشه اش رسول خدا صلی الله علیه و آلهاست و شاخه اش علی بن ابی طالب علیه السلام. سوگند به خدا ما (اهل بیت) میوه آن درختیم، پس هر کس به یکی از شاخه های آن چنگ زند نجات می یابد (و سعادتمند است) و هر کس از آن جدا شود جایگاهش آتش است.»","at":"امام حسن (ع) — چهل حدیث «گهرهای حسنی» (حدیث ۴۰۶)"},{"id":"d066","by":"hasan","ar":"مَكارِمُ الأَخْلاقِ عَشَرَةٌ: صِدْقُ اللِّسانِ وَ صِدْقُ اليَأْسِحديث و إِعْطاءُ السائِلِ و حُسنُ الْخُلقِ وَ الْمُكافاةُ بِالصَنائِعِ وَ صِلَةُ الرَحِمِ وَالتَّذَمُّمُ عَلَى الْجارِ وَ مَعْرِفَةُ الْحَقِّ لِلصّاحِبِ، وَ قِرَى الضَّيْفِ وَ رَأْسُهُنَّ الْحَياءُ. حديث","fa":"امام حسن مجتبی علیه السلام فرمود: مکارم اخلاق ده چیز است: ۱. راستگوئی ۲. نومیدی راستین از غیر خدا ۳. بخشش به نیازمندان ۴. خوش خلقی ۵. پاداش در برابر خدمات دیگران ۶. پیوند و رفت و آمد با خویشاوندان ۷. حمایت از همسایه ۸. توجّه به حقوق دوستان ۹. مهمان نوازی ۱۰. و مهمترین اینها شرم و حیاء است.","at":"امام حسن (ع) — چهل حدیث «گهرهای حسنی» (حدیث ۴۰۷)"},{"id":"d067","by":"hasan","ar":"«أَمّا بَعْدُ فَإنَّ عَلِيّا بابٌ مَنْ دَخَلَهُ كانَ آمِنا وَمَنْ خَرَجَ مِنْهُ كانَ كافِرا، أَقُولُ قَوْلِي هَذا، وَأَسْتَغْفِرُ اللّهَ لِي وَلَكُمْ.» حديث","fa":"امام مجتبی علیه السلام در حضور پدر گرامی اش خطبه ای خواند که در بخشی از آن فرمود: «همانا علی بن ابی طالب علیه السلام دربی است که هرکس بر آن وارد شود؛ یعنی او را بشناسد و بر او اقتدا کند، آرامش و امنیت کامل را درمی یابد و هرکس به آن درب روی نیاورد و مخالفت با او کند کفر و بدبختی و تیره روزی او را فرا خواهد گرفت، سپس فرمود: این گفته و مطلب اساسی من است، آنگاه برای خود و دیگران طلب رحمت و آمرزش نموده و گفت: استغفر اللّه لی ولکم و آنگاه از منبر فرود آمد.»","at":"امام حسن (ع) — چهل حدیث «گهرهای حسنی» (حدیث ۴۰۸)"},{"id":"d068","by":"hasan","ar":"«وَاللّهِ لا يُحِبُّنا عَبْدٌ أَبَدا وَلَوْ كانَ أَسيرا فِى الدَّيْلَمِ إلاّ نَفَعَهُ حُبُّنا وَإنَّ حُبَّنا لَيُساقِطُ الذُّنُوبَ مِنْ بَنِيآدَمَ كَما يُساقِطُ الريحُ الوَرَقَ مِنَ الشَّجَرِ.» حديث","fa":"امام حسن مجتبی علیه السلام فرمود: «سوگند به خداوند که کسی دوست نمی دارد ما را گر چه در دورترین نقاط؛ همچون دیلمحدیث اسیر باشد مگر این که دوستی ما به حال او مفید خواهد بود، همانا ولایت و محبت ما اهل بیت گناهان فرزندان آدم را از بین می برد همان طوری که باد، برگ درختان را از شاخه و تنه او جدا می کند و به زمین می ریزد.»","at":"امام حسن (ع) — چهل حدیث «گهرهای حسنی» (حدیث ۴۰۹)"},{"id":"d069","by":"hasan","ar":"النّاسُ فِي دارِ سَهْوٍ وَ غَفْلَةٍ يَعْمَلُونَ وَلا يَعْلَمُونَ فَاِذا صارُوا إلى الآخِرَةِ صارُوا اِلى دارِ يَقينٍ يَعْلَمُونَ وَ لا يَعْمَلُونَ. حديث","fa":"امام حسن مجتبی علیه السلام فرمود: مردم] در این دنیا] در خانه بی خبری و غفلت بسر می برند، پس هر کاری را انجام می دهند، نمی دانند [ثمرش را] و چون به خانه آخرت روند، به وادی یقین در آیند و همه چیز را بدانند و لکن نتوانند عمل سودمندی را در آنجا برای خویش انجام دهند.","at":"امام حسن (ع) — چهل حدیث «گهرهای حسنی» (حدیث ۴۱۰)"},{"id":"d070","by":"hasan","ar":"«إنَّما هذَا الأمْرُ لِي وَالخِلافَةُ لِي وَلِأهْلِ بَيْتِي، وَإنَّها لَُمحَرَّمَةٌ عَلَيْكَ وَعَلى أَهْلِ بَيْتِكَ سِمِعْتُهُ مِنْ رَسُولِ اللّهِ صلي الله عليه و آله. وَاللّهِ لَوْ وَجَدْتُ صابِرينَ عارِفينَ بِحَقّى غَيْرَمُنْكِرينَ ما سَلَّمْتُ لَكَ وَلا أَعْطَيْتُكَ ما تُريدُ.» حديث","fa":"امام مجتبی علیه السلام در پاسخ به نامه ای که معاویه برای آن حضرت فرستاده بود، چنین جواب دادند: «همانا این امر (حکومت) و جانشینی رسول خدا صلی الله علیه و آله از آنِ من و مربوط به اهل بیت من است و بر تو و خاندانت حرام است. این مطلب را از رسول خدا صلی الله علیه و آلهشنیده ام. سپس فرمود: سوگند به خداوند، چنانچه یارانی آگاه و آشنا به حقم، می یافتم (که در راه احیای حق ایستادگی می نمودند) حکومت را به تو واگذار نمی کردم و آنچه را که تو می خواستی، به تو نمی دادم».","at":"امام حسن (ع) — چهل حدیث «گهرهای حسنی» (حدیث ۴۱۱)"},{"id":"d071","by":"hasan","ar":"«وَاللّهِ لَقَدْ عَهِدَ إلَيْنا رَسُولُ اللّهِ يَمْلِكُهُ إثناعَشَرَ إماما مِنْ وُلْدِ عَلِيٍّ وَفاطِمَةَ، ما مِنّا إلاّ مَسْمُومٌ أَوْ مَقْتُولٌ.» حديث","fa":"جناده گوید: در روزهای واپسین عمر امام مجتبی علیه السلامخدمت آن حضرت رسیدم، آن حضرت به من نگاهی کرد و فرمود: «سوگند به خداوند که رسول خدابما وعده نمود: امامت و وصایت بعد از او را دوازده نفر بدست می گیرند، یازده نفر آنان از فرزندان علی وفاطمه علیهماالسلام هستند. سپس حضرت فرمود: ما جانشینان او در فرجام کار، در راه خدا یا مسموم می گردیم و یا کشته می شویم.»","at":"امام حسن (ع) — چهل حدیث «گهرهای حسنی» (حدیث ۴۱۲)"},{"id":"d072","by":"hasan","ar":"قالَ لَهُ رَجُلٌ: «يابنَ رَسُولِ اللّهِ إنّى مِن شيعَتِكُم» فَقالَ الحَسَن عليه السلام: «يا عَبْدَ اللّهِ إنْ كُنْتَ لَنا فِى أَوامِرِنا وَزَواجِرِنا مُطيعا فَقَدْ صَدَقْتَ، وَإنْ كُنْتَ بِخِلافِ ذلِكَ فَلا تَزِدْ فِي ذُنُوبِكَ بِدَعْواكَ مَرْتَبَةً شَريفَةً لَسْتَ مِنْ أَهْلِها، لا تَقُلْ أَنَا مِنْ شِيعَتِكُمْ ولكِنْ قُلْ أَنَا مِنْ مُوالِيكُمْ وَمُحِبِّيكُمْ وَمُعادِي أَعْدائِكُمْ وَأَنتَ فِى خَيْرٍ وَإلى خَيْرٍ.» حديث","fa":"مردی رو به امام حسن علیه السلام کرد و سپس گفت: «ای پسر رسول خدا من شیعه شما هستم.» امام علیه السلام فرمود: «ای بنده خدا، اگر در انجام واجبات و خودداری از محرمات (گناهان) پیرو ما هستی و تبعیت می کنی که راست می گویی، و چنانچه اینگونه نیستی، با این ادّعای دروغ بر گناهان خود افزودی؛ زیرا شیعه و پیرو ما از مقام والا و بلندی برخوردار است و تو اهل آن نیستی، مگو که من شیعه تو هستم، بلکه بگو من از دوستان و هواداران و نیز از بدخواهان دشمنان شمایم، در این صورت تو در خیر و نیکی بسر می بری و در مسیر خیر خواهی قرار داری.»","at":"امام حسن (ع) — چهل حدیث «گهرهای حسنی» (حدیث ۴۱۳)"},{"id":"d073","by":"hasan","ar":"«قال عليه السلام: إيّاكَ أَنْ تَمْدَحَنى فَأَنا أَعْلَمُ بِنَفْسى مِنْكَ أَوْ تُكَذِّبَنى فَإنَّهُ لا رَأْىَ لِمَكْذُوبٍ أَوْ تَغْتابَ عِنْدِى أَحَدا، فَقالَ لَهُ الرَجُلُ: إئذِنْ لِي فِى الإنْصِرافِ. فَقالَ عليه السلام: نَعَمْ إذا شِئْتَ.» حديث","fa":"مردی از امام حسن علیه السلام خواست که دوست و همنشین وی باشد، امام علیه السلام سه شرط را برایش مطرح نمود: «فرمود: ۱ اوّل آن که از من ستایش و تعریف نکنی؛ زیرا من نسبت به خودم از تو آگاه ترم. ۲ مرا دروغگو ندانی؛ زیرا دروغگو رأی و عقیده درستی ندارد. ۳ مبادا در برابر من از کسی غیبت کنی. چون آن مرد شرایط دوستی با آن حضرت را دشوار دید گفت:","at":"امام حسن (ع) — چهل حدیث «گهرهای حسنی» (حدیث ۴۱۴)"},{"id":"d074","by":"hasan","ar":"فقال عليه السلام: هِيَ أَنْ تَرْعى حُقُوقَ اللّهِ، حُقُوقَ الأحْياءِ، وَحُقُوقَ الأمواتِ. فَأمّا حُقُوقُ اللّهِ فَأداءُ ما طُلِبَ وَاجْتِنابُ عَمّا نُهِىَ. وَأمّا حُقُوقُ الأحْياءِ: فَهِىَ أَنْ تَقُومَ بِواجِبِكَ نَحْوَ إخْوانِكَ، وَلا تَتَأخَّرَ عَنْ خِدْمَةِ أُمَّتِكَ وَأَنْ تُخَلِّصَ لِوَلِىِّ الأمْرِ ما أَخْلَصَ لِأُمَّتِهِ وأنْ تَرْفَعَ عَقِيرَتَكَ فِى وَجْهِهِ إذا ما حادَ عَنِ الطَّريقِ السَويّ. وأمّا حُقُوقُ الأمواتِ: فَهِىَ أنْ تُذْكَرَ خَيْراتِهِمْ وَتَتَغاضى عَنْ مَساوِئِهِمْ فَإنَّ لَهُمْ رَبّا يُحاسِبُهُمْ. حديث","fa":"مردی از امام مجتبی علیه السلام پرسید: سیاست چیست؟ فرمود: «سیاست، رعایت حقوق خدا، و حقوق زندگان از مردم و حقوق اموات آنان است. اما حق خداوند: انجام دادن فرایض (واجبات) و دوری کردن از آنچه ما را نهی کرده است (محرّمات). اما حقوق زندگان: این که وظیفه خود را نسبت به مردم انجام دهی و هرگز از خدمت","at":"امام حسن (ع) — چهل حدیث «گهرهای حسنی» (حدیث ۴۱۵)"},{"id":"d075","by":"hasan","ar":"«لَوْ جَعَلْتُ الدُنْيا كُلَّها لُقْمَةً واحِدَةً لَقَمْتُها مَنْ يَعْبُدُ اللّهَ خالِصا لَرَأَيْتُ أَنّى مُقَصِّرٌ فِى حَقِّهِ، وَلَوْ مَنَعْتُ الكافِرَ مِنْها حَتّى يَمُوتَ جُوعا وَعَطَشا ثُمَّ أَذَقْتُهُ شَرْبَةً مِنَ الماءِ لَرَأَيْتُ أَنّى قَدْ أَسْرَفْتُ.» حديث","fa":"امام مجتبی علیه السلام فرمود: «اگر همه دنیا را تبدیل به یک لقمه غذا کنم و به انسانی که خدا را از روی خلوص عبادت می کند بخورانم، درباره او کوتاهی کرده و خودم را مقصّر می دانم و چنانچه فرد کافری را گرسنگی دهم تا به آن اندازه که جانش از شدّت گرسنگی و تشنگی به لب برسد، آنگاه مقداری کمی آب به او بدهم، خود را نسبت به او اسراف کار می پندارم.»","at":"امام حسن (ع) — چهل حدیث «گهرهای حسنی» (حدیث ۴۱۶)"},{"id":"d076","by":"hasan","ar":"يا بُنَيَّ لا تُؤاخِ أَحَدا حَتّى تَعْرِفَ مَوارِدَهُ وَمَصادِرَهُ فَإذا اسْتَنْبَطْتَ الخُبْرَةَ وَرَضِيتَ العِشْرَةَ فَآخِهِ عَلى إقالَةِ العَثْرَةِ وَالمُواساةِ فِى العُسْرَةِ.» حديث","fa":"امام مجتبی علیه السلام فرمود: «پسرم با هیچ کس پیمان دوستی مبند مگر این که بدانی از کجا می آید و به کجا می رود؛ یعنی خصوصیات اخلاقی و خانوادگی اش را بدست آور، و چون دقیق بررسی کردی و او را انسانی شایسته یافتی، بر پایه گذشت و اغماض و برادری در سختیها و لغزشها با او رفتار کن و دوستی ات را استمرار بخش.»","at":"امام حسن (ع) — چهل حدیث «گهرهای حسنی» (حدیث ۴۱۷)"},{"id":"d077","by":"hasan","ar":"«أَعْرَفُ الناسِ بِحُقُوقِ إخوانِهِ وَأَشَدُّهُمْ قَضاءا لَها أَعْظَمُهُمْ عِنْدَاللّهِ شَأْنا وَمَنْ تَواضَعَ فِى الدُّنْيا لاِءخْوانِهِ فَهُوَ عِنْدَاللّهِ مِنَ الصِّدِيقينَ وَ مِنْ شيعَةِ عَلِيِّ بْنِ أَبىطالِبٍ عليه السلام » حديث","fa":"امام مجتبی علیه السلام فرمود: «والاترین مقام در نزد خداوند از آن کسی است که آشنا به حقوق مردم باشد وسعی در ادای آن نمایند، وکسی که در برابر برادران دینی اش تواضع داشته باشد، خداوند او را از راستگویان وشیعیان علی بن ابیطالب علیه السلاممحسوب خواهد کرد.»","at":"امام حسن (ع) — چهل حدیث «گهرهای حسنی» (حدیث ۴۱۸)"},{"id":"d078","by":"hasan","ar":"اَلْمَعْرُوفُ مالَمْ يَتَقَدَّمَّهُ مَطَلٌ وَلا يَتْبَعُهُ مَنٌّ وَ الإعْطاءُ قَبْلَ السُؤالِ مِنْ أكْبَرِ السُؤدَدْ. حديث","fa":"امام مجتبی علیه السلام فرمود: کار نیک آن است که قبل از انجامش هیچگونه سستی و مسامحه ای انجام نگیرد و بعد از پایان کار هیچ منّتی همراه نداشته باشد] بعد فرمود: [بخشندگی قبل از سؤال کردن نشانه بزرگواری است.","at":"امام حسن (ع) — چهل حدیث «گهرهای حسنی» (حدیث ۴۱۹)"},{"id":"d079","by":"hasan","ar":"إِنَّ اللّهَ تَعالَى يُباهي مَلائِكَتَهُ بِعِبادِةِ يَوْمِ عَرَفَةِ فَيَقُولُ: عِباِدي جاؤُنِي شُعْثا يَتَعَرَّضُونَ لِرَحْمَتِي فَأُشْهِدُكُمْ أَنِّي قَدْ غَفَرَتُ لُِمحْسِنِهِمْ وَ شَفَّعْتُ مُحْسِنَهُمْ فِيمُسِيئِهِمْ وَإِذا كانَ يَوْمَ الْقِيامَةِ فَمِثْلُ ذلِكَ. حديث","fa":"امام حسن علیه السلام فرمود: همانا خداوند مباهات و افتخار به بندگانِ خود در سرزمین عرفات می کند و به فرشتگان خود می گوید: بندگانِ من بر روی خاکها نشسته اند و طلب رحمت می کنند گواه باشید که من نیکوکاران آنها را بخشیدم و آنان را شافع و واسطه در بخشش گناهکاران آنها قرار دادم و به هنگام قیامت نیز آنان شفاعت می کنند.","at":"امام حسن (ع) — چهل حدیث «گهرهای حسنی» (حدیث ۴۲۰)"},{"id":"d080","by":"hussain","ar":"نَحْنُ حِزْبُ اللّهِ الْغالِبُونَ، وَعِتْرَةُ رَسُولِ اللّهِ صلي الله عليه و آلهالاَْقْرَبُونَ، وَاَهْلُ بَيْتِهِ الطَّيِّبُونَ، وَأَحَدُالثَّقَلَيْنِ الَّذينَ جَعَلَنا رَسُولُ اللّهِ ثانِىَ كِتابِ اللّهِ... حديث","fa":"امام حسین علیه السلام فرمود: ما حزب اللّه پیروزیم، و عترت نزدیکتر رسول خدا و خاندان پاک اوییم، و ما یکی از دو وزنه سنگینیم که رسول خدا ما را همتای کتاب خدا قرار داده است.","at":"امام حسین (ع) — چهل حدیث «گهرهای حسینی» (حدیث ۵۰۲)"},{"id":"d081","by":"hussain","ar":"مَنْ أحَبَّنا لايُحِبُّنا إلاّ لِلّهِ، جِئْنا نَحْنُ وَهُوَ كَهاتَيْنِ وَقَدَّرَ بَيْنَ سَبّابَتَيْهِ وَمَنْ أَحَبَّنا لايُحِبُّنا إلاّ لِلدُّنْيا، فَإنَّهُ إذا قامَ قائِمُ الْعَدْلِ وَسِعَ عَدْلُهُ الْبِرَّ وَالْفاجِرَ. حديث","fa":"امام حسین علیه السلام فرمود: کسی که ما را تنها، بخاطر خدا دوست بدارد، ما و او مثل این دو (اشاره به دو انگشت) می آییم، و کسی که ما را بخاطر دنیا هم دوست داشته باشد (باز مفید است زیرا) هنگامی که امام زمان علیه السلام ظهور کند، عدالت او شامل خوب و بد می شود.","at":"امام حسین (ع) — چهل حدیث «گهرهای حسینی» (حدیث ۵۰۳)"},{"id":"d082","by":"hussain","ar":"اَيُّهَا النّاسُ! اِنَّ اللّهَ جَلَّ ذِكْرُهُ ماخَلَقَ الْعِبادَ اِلاّ لِيَعْرِفُوهُ، فَاِذا عَرَفُوهُ عَبَدُوهُ، فَإذا عَبَدُوهُ اسْتَغْنُوا بِعِبادَتِهِ عَنْ عِبادَةِ ماسِواهُ. فَقالَ لَهُ رَجُلٌ: يَابْنَ رَسُولِ اللّهِ بِأَبى أَنْتَ وَاُمّي فَما مَعْرِفَةُ اللّهِ؟ قالَ: «مَعْرِفَةُ أَهْلِ كُلِّ زَمانٍ إِمامَهُمْ اَلَّذى يَجِبُ عَلَيْهِمْ طاعَتُهُ.» حديث","fa":"امام حسین علیه السلام فرمود: ای مردم! همانا خدای بزرگ بندگان را نیافریده مگر برای آنکه او را بشناسند، وقتی او را شناختند او را پرستش خواهند کرد، هنگامی که او را پرستش کردند از بندگی غیر او بی نیاز می شوند. مردی گفت: ای فرزند رسول خدا، پدر و مادرم فدایت باد، شناخت خدا چیست؟ فرمود: عبارتست از شناخت مردم هر زمان امامشان را، آن امامی که اطاعت او بر آنها واجب است.","at":"امام حسین (ع) — چهل حدیث «گهرهای حسینی» (حدیث ۵۰۴)"},{"id":"d083","by":"hussain","ar":"ما كُنّا نَعْرِفُ الْمُنافِقِينَ عَلى عَهْدِ رَسُولِ اللّهِ صلي الله عليه و آله اِلاّ بِبُغْضِهِمْ عَليّاً وَوُلْدَهُ عليه السلام. حديث","fa":"امام حسین علیه السلام فرمود: ما زمان رسول خدا صلی الله علیه و آله، منافقین را فقط با دشمنی با علی علیه السلام و فرزندان او می شناختیم.","at":"امام حسین (ع) — چهل حدیث «گهرهای حسینی» (حدیث ۵۰۵)"},{"id":"d084","by":"hussain","ar":"مَنْ دَمَعَتْ عَيْناهُ فينا دَمْعَةً بِقَطْرَةٍ اَعْطاهُ اللّهُ تَعالى الْجَنَّةَ. حديث","fa":"امام حسین علیه السلام فرمود: کسی که چشمانش قطره ای اشک برای ما بریزد، خداوند بهشت را به او عطا خواهد کرد.","at":"امام حسین (ع) — چهل حدیث «گهرهای حسینی» (حدیث ۵۰۶)"},{"id":"d085","by":"hussain","ar":"لَوْلَمْ يَبْقَ مِنَ الدُّنْيا إلاّيَوْمٌ واحِدٌ لَطَوَّلَ اللّهُ عَزَّوَجَلَّ ذلِكَ الْيَوْمَ حَتّى يَخْرُجَ رَجُلٌ مِنْ وُلْدى، فَيَمْلاَءُها عَدْلاً وَقِسْطاً كَما مُلِئَتْ جَوْراً وَظُلْماً، كَذلِكَ سَمِعْتُ رَسُولَ اللّهِ صلي الله عليه و آلهيَقُول. حديث","fa":"امام حسین علیه السلامفرمود: اگر از دنیا بجز یک روز باقی نمانده باشد، خداوند آن روز را طولانی خواهد کرد تا اینکه مردی از خاندان من ظهور کند، و دنیا را پر از عدل و داد کند همانگونه که از ظلم و ستم پر شده است، از رسول خدا صلی الله علیه و آله چنین شنیدم.","at":"امام حسین (ع) — چهل حدیث «گهرهای حسینی» (حدیث ۵۰۷)"},{"id":"d086","by":"hussain","ar":"يا ابْنَ رَسُولِ اللّهِ أَنَا مِنْ شيعَتِكُمْ، قالَ: اتَّقِ اللّهَ وَ لا تَدّْعِيَنَّ شَيْئاً يَقُولُ اللّهُ لَكَ كَذِبْتَ وَفَجَرْتَ فِى دَعْواكَ، إِنَّ شيعَتَنا مَنْ سَلُمَتْ قُلُوبُهُمْ مِنْ كُلِّ غِشٍّ وَغِلٍّ وَدَغَلٍ، وَلكِنْ قُلْ أَنَا مِنْ مَوالِيكُمْ وَمُحِبّيكُمْ. حديث","fa":"مردی به امام حسین علیه السلام گفت: ای فرزند رسول خدا من از شیعیان شمایم، فرمود: از خدا بترس! چیزی را ادّعا نکن که خدا بگویدت دروغ گفتی و ادّعای گزافی کردی، شیعیان ما کسانی اند که دلهایشان از هر نوع غلّ و غشّ و دغلکاری پاک باشد، ولی تو بگو: من از دوستان و علاقه مندان شمایم.","at":"امام حسین (ع) — چهل حدیث «گهرهای حسینی» (حدیث ۵۰۸)"},{"id":"d087","by":"hussain","ar":"لِيَكُنْ كُلُّ امْرِئٍ مِنْكُمْ حِلْساً مِنْ اَحْلاسِ بَيْتِهِ مادامَ هذَا الرَّجُلُ حَيّاً فَاِنْ يُهْلَكْ وَاَنْتُمْ أحْياءٌ رَجَوْنا اَنْ يُخَيِّرَاللّهُ لَنا وَيُؤْتينا رُشْدَنا وَلا يَكِلَنا اِلى انْفُسِنا، «اِنَ اللّهَ مَعَ الَّذينَ اتَّقَوا وَالَّذينَ هُمْ مُحْسِنُون.»َحديث حديث","fa":"امام حسین علیه السلام فرمود: هریک از شما تا زمانی که این مرد (معاویه) زنده است خانه نشین در خانه خودش باشد (یعنی حرکتی نکند) پس وقتی که او به هلاکت رسید و شما زنده بودید امید است که خداوند رشد و رستگاری را برای ما برگزیند و ما را بخودمان وامگذارد، (همانطور که در قرآن وعده فرموده است که) خدا با کسانی است که تقوا پیشه کنند و کار نیکو انجام دهند.","at":"امام حسین (ع) — چهل حدیث «گهرهای حسینی» (حدیث ۵۰۹)"},{"id":"d088","by":"hussain","ar":"اِنّا لِلّهِ وَاِنّا اِلَيْهِ راجِعُونَ وَعَلَى الاِْسْلامِ الْسَّلامُ اِذ قَدْ بُلِيَتِ الاُْمَّةُ بِراعٍ مِثْلَ يَزيدَ، وَلَقَدْ سَمِعْتُ رَسُولَ اللّهِ صلي الله عليه و آلهيَقُولُ: اَلْخِلافَةُ مُحَرَّمَةٌ عَلى آلِ اَبى سُفيانَ. حديث","fa":"امام حسین علیه السلام(در پاسخ به پیشنهاد مروان بن حکم که با یزید بیعت کن) فرمود: در این صورت باید گفت: انا للّه و انا الیه راجعون و فاتحه اسلام را خواند زیرا امّت اسلام گرفتار چوپانی همانند یزید شده است و من خودم از رسول خدا صلی الله علیه و آله شنیدم که می فرمود: خلافت بر آل ابوسفیان حرام است.","at":"امام حسین (ع) — چهل حدیث «گهرهای حسینی» (حدیث ۵۱۰)"},{"id":"d089","by":"hussain","ar":"أَلا وَاِنَّ الدَّعِىَّ ابْنَ الدَّعِىِّ قَدْ تَرَكَنى بَيْنَ السِلَّةِ وَالذِّلَةِ، وَهَيْهاتَ لَهُ ذلِكَ مِنّى! هَيْهاتَ مِنَّاالذِّلَّةِ!! أَبَى اللّهُ ذلِكَ لَنا وَرَسُولُهُ وَالْمُؤْمِنُونَ وَ حُجُورٌ طَهُرَتْ وَ جُدُودٌ طابَتْ، اَنْ يُؤْثِرَ طاعَةَ اللِّئامِ عَلى مَصارِعِ الْكِرامِ. حديث","fa":"امام حسین علیه السلام(در روز عاشورا) فرمود: آگاه باشید این حرام زاده پسر حرام زاده ما را میان شمشیر کشیده و خواری (بیعت) قرار داده ولی خواری و ذلّت از ما بدور است، ما و ذلّت هرگز! ! خداوند و پیامبرش و مؤمنان و دامنهای پاک و دودمان پاکیزه برای ما نپسندیدند که فرمان برداری از پست فطرتان را بر جنگ با عزّت برگزینیم.","at":"امام حسین (ع) — چهل حدیث «گهرهای حسینی» (حدیث ۵۱۱)"},{"id":"d090","by":"hussain","ar":"مَوْتٌ في عِزٍّ خَيْرٌ مِنْ حَياةٍ في ذُلٍّ اَلْمَوْتُ اَوْلى مِنْ رُكُوبِ الْعارِ وَالْعارُ اَوْلى مِنْ دُخُولِ النّارِ حديث","fa":"امام حسین علیه السلام(روز عاشورا) فرمود: مرگ با عزّت از زندگی ذلیلانه برتر است. مرگ برتر از همراه شدن با عار و خواری است و خواری از ورود در آتش برتر است","at":"امام حسین (ع) — چهل حدیث «گهرهای حسینی» (حدیث ۵۱۲)"},{"id":"d091","by":"hussain","ar":"وَيْحَكُمْ يا شِيعَةَ آلِ اَبى سُفْيانَ، اِنْ لَمْ يَكُنْ لَكُمْ دِيْنٌ وَكُنْتُمْ لاتَخافُونَ الْمَعادَ فَكُونُوا اَحْراراً فِى دُنْياكُمْ. حديث","fa":"امام حسین علیه السلام فرمود: وای بر شماای پیروان آل سفیان، اگر دین ندارید و از روز قیامت نمی ترسید، پس حداقلّ در دنیای خودتان آزادمرد باشید.","at":"امام حسین (ع) — چهل حدیث «گهرهای حسینی» (حدیث ۵۱۳)"},{"id":"d092","by":"hussain","ar":"لَيْسَ شَأْنى شَأنُ مَنْ يَخافُ الْمَوْتَ، ما أَهْوَنَ الْمَوْتِ عَلى سَبيلِ نَيْلِ الْعِزِّ وَاِحْياءِ الْحَقِّ، لَيْسَ الْمَوْتُ في سَبيلِ الْعِزِّ اِلاّ حَياةً خالِدَةً وَلَيْسَتِ الْحَياةُ مَعَ الذُّلِّ اِلاَّالْمَوْتَ الَّذى لاحَياةَ مَعَهُ، اَفَبِالْمَوْتِ تُخَوِّفُنى... وَهَلْ تَقْدِرُونَ عَلى أَكْثَرِ مِنْ قَتْلى؟! مَرْحَباً بِالْقَتْلِ فيسَبيلِ اللّهِ، وَلكِنَّكُمْ لاتَقْدِروُنَ عَلى هَدْمِ مَجْدى وَمَحْوِ عِزّى وَشَرَفى. حديث","fa":"امام حسین علیه السلامفرمود: جایگاه من جایگاه کسی که از مرگ بترسد نیست مرگ در راه عزّت و احیای حقّ چقدر پیش من آسان است، مرگ در راه عزّت چیزی جز حیات جاودانه نیست و زندگی با ذلّت جز مرگ و نیستی که هیچ حیاتی همراه ندارد نیست، آیا مرا با مرگ می ترسانید. آیا بیش از کشتن من می توانید؟ آفرین به مرگ در راه خدا، ولی شما نمی توانید شکوه مرا نابود کنید و عزّت و شرافتم را از بین ببرید.","at":"امام حسین (ع) — چهل حدیث «گهرهای حسینی» (حدیث ۵۱۴)"},{"id":"d093","by":"hussain","ar":"سُئِلَ الاِْمامُ الْحُسَيْنُ عليه السلام عَنِ الاَْدَبِ، فَقالَ: هُوَ اَنْ تَخْرُجَ مِنْ بَيْتِكَ، فَلا تُلْقِىَ اَحَداً اِلاّ رَأَيْتَ لَهُ الْفَضْلَ عَلَيْكَ. حديث","fa":"از امام حسین علیه السلاممعنای ادب را پرسیدند؟ امام علیه السلام فرمود: ادب عبارتست از اینکه وقتی که از خانه خارج می شوی به هرکسی برخورد می کنی او را برتر از خود بینی. (یعنی همیشه دیگران را از خود بهتر بینی و احترام آنها را نگهداری)","at":"امام حسین (ع) — چهل حدیث «گهرهای حسینی» (حدیث ۵۱۵)"},{"id":"d094","by":"hussain","ar":"خَمْسٌ مَنْ لَمْ تَكُنْ فِيهِ، لَمْ يَكُنْ فِيهِ كَثيرُ مُسْتَمْتَعٍ: اَلْعَقْلُ، وَالدّينُ وَالْأَدَبُ، وَالْحَياءُ، وَحُسْنُ الْخُلْقِ. حديث","fa":"امام حسین علیه السلام فرمود: پنج چیز است اگر در انسان نباشد، در او بهره زیادی نخواهد بود: ۱عقل ۲ دین ۳ ادب ۴ حیا ۵ خوش اخلاقی.","at":"امام حسین (ع) — چهل حدیث «گهرهای حسینی» (حدیث ۵۱۶)"},{"id":"d095","by":"hussain","ar":"لا اَفْلَحَ قَوْمِ اشْتَرَوْا مَرْضاةَ الْمَخْلُوقِ بِسَخَطِ الْخالِقِ. حديث","fa":"امام حسین علیه السلام فرمود: ملّتی که خشنودی مردم را با خشم خدا معامله کند هرگز رستگار نخواهد شد.","at":"امام حسین (ع) — چهل حدیث «گهرهای حسینی» (حدیث ۵۱۷)"},{"id":"d096","by":"hussain","ar":"اَلصِّدْقُ عِزٌّ، وَالْكِذْبُ عَجْزٌ، وَالسِّرُّ اَمانَةٌ، وَالْجِوارُ قَرابَةٌ، وَالْمَعُونَةُ صَداقَةٌ، وَالْعَمَلُ تَجْرِبَةٌ. حديث","fa":"امام حسین علیه السلام فرمود: راستگویی بزرگواری است و دروغگویی ناتوانی، رازداری امانت است، و همسایگی خویشاوندی و کمک کردن صداقت است و کار، تجربه.","at":"امام حسین (ع) — چهل حدیث «گهرهای حسینی» (حدیث ۵۱۸)"},{"id":"d097","by":"hussain","ar":"لِلسَّلامِ سَبْعُونَ حَسَنَةً تِسْعٌ وَسِتُّونَ لِلْمُبْتَدِى وَواحِدَةٌ لِلرّادِّ. حديث","fa":"امام حسین علیه السلام فرمود: سلام، هفتاد حسنه دارد، شصت و نه حسنه برای سلام کننده و یکی برای پاسخ دهنده است.","at":"امام حسین (ع) — چهل حدیث «گهرهای حسینی» (حدیث ۵۱۹)"},{"id":"d098","by":"sajjad","ar":"لايَقِلُّ عَمَلٌ مَعَ تَقْوى وَكَيْفَ يَقِلُّ مايُتقَبَّلُ. حديث","fa":"امام سجاد علیه السلام فرمود: کاری که با تقوا همراه باشد اندک نیست، چگونه آنچه مقبول خدا قرار گرفته، اندک محسوب شود.","at":"امام سجاد (ع) — چهل حدیث «گهرهای سجادی» (حدیث ۶۰۱)"},{"id":"d099","by":"sajjad","ar":"اِيّاكَ وَالاِْبْتِهاجَ بالِذَّنْبِ، فاِنَّ الاِْبْتِهاجَ بِهِ اَعْظَمُ مِنْ ركُوُبِهِ. حديث","fa":"امام چهارم علیه السلام فرمود: مبادا به گناهی که انجام داده ای خوشحال باشی، زیرا اظهار شادی بخاطر گناه از انجام آن «گناه» بزرگتر است.","at":"امام سجاد (ع) — چهل حدیث «گهرهای سجادی» (حدیث ۶۰۲)"},{"id":"d100","by":"sajjad","ar":"ما اَكَلْتُ بِقِرابَتى بِرَسُولِ اللّهِ شَيْئا قَطُّ. حديث","fa":"امام سجاد علیه السلام فرمود: هیچگاه به دلیل انتساب به پیامبرخدا صلی الله علیه و آله چیزی نخوردم «و از آبروی آن بزرگوار به سود خود استفاده نکردم».","at":"امام سجاد (ع) — چهل حدیث «گهرهای سجادی» (حدیث ۶۰۳)"},{"id":"d101","by":"sajjad","ar":"وَيْحَكَ اَفى حَرَمِ اللّهِ اَسْأَلُ غَيْرَاللّهِ عَزَّوَجَلَّ؟!! اِنّى آنِفُ اَنْ اَسْأَلَ الدُّنْيا خالِقَها، فَكَيْفَ اَسْأَلُها مَخْلُوقا مِثْلى؟! حديث","fa":"کسی به حضرت گفت: حال که ولید بن عبدالملک در مکّه است، نزد او برو و از او بخواه در مورد تولیّت اوقاف و صدقات علی بن ابی طالب علیه السلام از تو حمایت کند. امام چهارم فرمود: بیچاره! در حرم خدا از غیرخدا چیزی درخواست کنم؟ ! ! براستی من خوش ندارم که از آفریننده جهان، دنیا را درخواست کُنم، چگونه آن را از مخلوقی همچون خود درخواست نمایم.","at":"امام سجاد (ع) — چهل حدیث «گهرهای سجادی» (حدیث ۶۰۴)"},{"id":"d102","by":"sajjad","ar":"اِنَّما الاِْسْتِعْدادُ لْلِمَوْتِ تَجنُّبُ الْحرامِ وَبَذْلُ النَّدى فى الْخَيْرِ. حديث","fa":"امام زین العابدین علیه السلام فرمود: براستی آمادگی برای مرگ، دوری از حرام و بذل و بخشش در کار خیر است.","at":"امام سجاد (ع) — چهل حدیث «گهرهای سجادی» (حدیث ۶۰۵)"},{"id":"d103","by":"sajjad","ar":"عَنْ اَبى عَبْداللّه: قالَ: اِنَّ عَلَّى بَنُ الْحُسينِ صَلَواتُ اللّهِ عَلَيْهِما اِسْتَقْبَلَهُ مَوْلىً لَهُ فى لَيْلَةٍ بارِدَةٍ وَعَلَيْهِ جُبَّةُ ومُطْرَفُ خَزٍّ وَعَمامَةُ خَزٍّ وَهُوَ مُتَغَلِّفٌ بالْغالِيَةِ فَقالَ لَهُ جُعِلْتُ فَداكَ فى مِثْلِ هذه الساعَةِ عَلى هذهِ الْهَيْئَة اِلى اَيْنَ؟ قالَ: فَقالَ: اِلى مَسْجِدِ جَدّى رَسُولِ اللّهِ صلي الله عليه و آله اَخْطُبُ الْحُورَ العينَ اِلَى اللّهِ عَزَّوَجَلّ. حديث","fa":"امام صادق علیه السلام فرموده است: یکی از غلامان امام چهارم آن بزرگوار را در شبی خنک دید. که. لباس خَزّ، روپوش «پالتو» خَزَّ و عمّامه خزّ «گرانبهائی» پوشیده و غرق بوی خوش است. به حضرت گفت: این موقع شب با این لباس به کجا می روید؟ امام صادق علیه السلام فرمود: امام سجاد علیه السلام چنین پاسخ داد: به مسجد جدّم رسول خدا صلی الله علیه و آلهمی روم تا از خدای عَزَّوَجَلَّ حورالعین را خواستگاری کنم!","at":"امام سجاد (ع) — چهل حدیث «گهرهای سجادی» (حدیث ۶۰۶)"},{"id":"d104","by":"sajjad","ar":"اِيّاكُمْ وَصَحْبَةَ الْعاصينَ وَمَعُونَهَ الظالِمينَ وَمجاوِرَة الْفاسقينَ اِحْذَروُا فِتْنَتَهُمْ وَتَباعِدُوا مِنْ ساحَتِهِمْ. حديث","fa":"امام سجاد علیه السلام فرمود: هشدار، از همنشینی گناهکاران و یاری ستمگران و همسایگی بدکاران بپرهیزید، از فتنه آنان برحذر باشید و از ناحیه آنان دور شوید.","at":"امام سجاد (ع) — چهل حدیث «گهرهای سجادی» (حدیث ۶۰۷)"},{"id":"d105","by":"sajjad","ar":"اِعْلَمُوا عِبادَ اللّهِ اَنَّ اَهْلَ الشِّرْكِ لايُنْصَبُ لَهُمْ اَلمَوازينَ وَلايُنْشَرُ لَهُم الدَّواوينَ وَاِنمّا يُحْشَرُونَ اِلى جَهَنَّمَ زُمَرا وَاِنمّا نَصْبُ الْمَوازينَ وَنَشْرُ الدَواوينَ لاَهِلِ الاِسْلامِ. حديث","fa":"امام سجاد علیه السلام فرمود: بندگان خدا! بدانید، بپاداشتن میزان و گشودن دیوان اعمال برای مشرکان نیست آنان دسته جمعی بسوی جهنّم محشور می شوند. نصب میزان و باز کردن دفتر اعمال ویژه اهل اسلام است.","at":"امام سجاد (ع) — چهل حدیث «گهرهای سجادی» (حدیث ۶۰۸)"},{"id":"d106","by":"sajjad","ar":"لَوْماتَ مَنْ بَيْنِ الْمَشْرِقِ وَالْمَغْرِبِ لَمَا اسْتَوْحَشْتُ بَعْدَ اَنْ يَكُونَ الْقُرآنُ مَعى. حديث","fa":"امام زین العابدین علیه السلام فرمود: اگر همه آنها که بین مشرق و مغرب هستند، بمیرند، تا وقتی قرآن با من باشد، احساس تنهائی نمی کنم.","at":"امام سجاد (ع) — چهل حدیث «گهرهای سجادی» (حدیث ۶۰۹)"},{"id":"d107","by":"sajjad","ar":"قَيلَ «للسَّجاد» عليه السلام اِنَّكَ اَبَرُّ الناسِ وَلاتَاكُلُ مَعَ اُمِّكَ فى قَصْعَةٍ وَهِىَ تُريدُ ذالِكَ. قالَ: اَكْرَهُ اَنْ تَسْبِقَ يَدِىَ اِلى ما سَبَقَتْ اِلَيْهِ عَيْنُها فَاَكُونَ عاقَّا لَها. حديث","fa":"به امام سجاد علیه السلام گفتند: شما که نیکوکارترین مردمی، چرا همراه با مادرت از یک کاسه غذا نمی خوری و حال آنکه مادرت بدین کار مایل است. فرمود: می ترسم دستم بسوی لقمه ای پیشی گیردکه قبلاً اوبدان چشم دوخته است و بدین گونه حق او را رعایت نکنم.","at":"امام سجاد (ع) — چهل حدیث «گهرهای سجادی» (حدیث ۶۱۰)"},{"id":"d108","by":"sajjad","ar":"يابُنّى ايّاكَ وَظُلْمَ مَنْ لايَجِدُ عليكَ ناصِرا اِلاّ اللّه. حديث","fa":"امام سجاد علیه السلام فرمود: فرزندم! بپرهیز از ستم بر کسی که یاوری جز خدا ندارد.","at":"امام سجاد (ع) — چهل حدیث «گهرهای سجادی» (حدیث ۶۱۱)"},{"id":"d109","by":"sajjad","ar":"فَقْدْ الاَْحِبَّةِ غُرْبَةٌ. حديث","fa":"امام زین العابدین علیه السلام فرمود: از دست دادن دوستان نوعی «غریبی» است.","at":"امام سجاد (ع) — چهل حدیث «گهرهای سجادی» (حدیث ۶۱۲)"},{"id":"d110","by":"sajjad","ar":"وَكانَ اِذا اَتاهُ السائِلُ يَقُول: مَرْحَبا بِمَنْ يَحْمِلُ لى زادى اِلىَ الآخِرَة. حديث","fa":"وقتی نیازمندی به نزد او می آمد چنین می فرمود: آفرین و خوشآمد! به کسی که توشه ی مرا بسوی آخرت حمل می کند.","at":"امام سجاد (ع) — چهل حدیث «گهرهای سجادی» (حدیث ۶۱۳)"},{"id":"d111","by":"sajjad","ar":"قالَ اَبُوحَمزَة الثُّمالى: كانَ زينُ العابِدين يَحْمِلُ جِرابَ الخُبزِ عَلى ظَهْرِه باللَّيْلِ فَيَتَصَّدَقُ بِهِ وَيَقُول: اِنَّ صَدَقَةَ السِّرِ تُطْفِى ءُ غَضَبَ الرَبِّ. حديث","fa":"ابوحمزه ثمالی نقل کرده که امام زین العابدین کیسه نان بدوش می گرفت و شبانه صدقه می داد و می فرمود: براستی صدقه پنهانی خشم خدا را فرومی نشاند.","at":"امام سجاد (ع) — چهل حدیث «گهرهای سجادی» (حدیث ۶۱۴)"},{"id":"d112","by":"sajjad","ar":"الرِّضا بِمَكْرُوهِ الْقَضاءِ اَرْفَعُ دَرَجاتِ الْيَقينِ. حديث","fa":"امام سجاد علیه السلام فرمود: خوشنودی به قضای ناخوشایند الهی عالی ترین پایه های ایمان و یقین است.","at":"امام سجاد (ع) — چهل حدیث «گهرهای سجادی» (حدیث ۶۱۵)"},{"id":"d113","by":"sajjad","ar":"وَالذّىَ بَعَثَ مُحمَّدا بِالْحَقِّ بَشيرا ونَذيرا اِنّ الاَْبْرارَ مِنّا اهلَ الْبَيْتِ وَشْيعَتِهِمْ بِمَنْزَلَةِ مُوسى وشيعَتِهِ وَاِنّ عَدُوَّنا وَاَشْياعَهِمْ بَمْنِزِلَةِ فِرْعَوْنَ وَاَشْياعِهِ. حديث","fa":"امام زین العابدین علیه السلام فرمود: سوگند به کسی که محمّد صلی الله علیه و آله را به عنوان مژده بخش و بیم رسان برانگیخت، نیکان ما اهل بیت و پیروان ما همانند موسی و شیعیان اویند و دشمنان ما و پیروان ایشان همانند فرعون و پیروان آنان محسوب می شوند.","at":"امام سجاد (ع) — چهل حدیث «گهرهای سجادی» (حدیث ۶۱۶)"},{"id":"d114","by":"sajjad","ar":"مَنْ قَنَعَ بِما قَسَّمَ اللّهُ لَهُ فَهُوَ مِنْ اَغْنَى الناسِ. حديث","fa":"امام چهارم علیه السلام فرمود: هر کس به تقسیم الهی قانع باشد از بی نیازترین مردم است.","at":"امام سجاد (ع) — چهل حدیث «گهرهای سجادی» (حدیث ۶۱۷)"},{"id":"d115","by":"sajjad","ar":"مَنْ اَعْظَمُ النّاسِ خَطَرا، قالَ: مَنْ لَمْ يَرَىَ الدّنيا خَطَرا لِنَفْسِهِ. حديث","fa":"به امام سجاد علیه السلام گفتند مهمترین مردم کیست؟ فرمود: آنکه دنیا را مایه ارزش خود نداند.","at":"امام سجاد (ع) — چهل حدیث «گهرهای سجادی» (حدیث ۶۱۸)"},{"id":"d116","by":"sajjad","ar":"عَجِبْتُ لِمَنْ يَحْتَمى مِنَ الطَّعامِ لِمَضَرَّتِهِ وَلايَحْتَمى مِنَ الذَّنْبِ لَمِعَرَّتَهِ. حديث","fa":"امام سجاد علیه السلام فرمود: در شگفتم از کسی که از غذا می پرهیزد تا گرفتار زیان آن نشود؛ ولی از گناه پرهیز نمی کند تا گرفتار ننگ و عار آن نگردد.","at":"امام سجاد (ع) — چهل حدیث «گهرهای سجادی» (حدیث ۶۱۹)"},{"id":"d117","by":"sajjad","ar":"نَظَرُ الْمُؤمِنِ فى وَجْهِ اخيهِ الْمُؤمِنِ لِلْمَوَدَّةِ وَالمَحَبَّةِ لَهُ عِبادَةٌ. حديث","fa":"امام زین العابدین علیه السلام فرمود: نگاه مؤمن از روی دوستی و مهربانی به سیمای برادر مؤمِنش عبادت است.","at":"امام سجاد (ع) — چهل حدیث «گهرهای سجادی» (حدیث ۶۲۰)"},{"id":"d118","by":"baqir","ar":"قالَ اللّه تَعالى:«كُلُ شَى ءٍ هالِكٌ الاّ وَجهَهُ» قالَ: فَيَهلِكُ كُلُّ شَى ءٍ وَ يَبْقَى الوَجْهُ اَنّ عَزَّوَجَلَّ اَعْظَمُ مِنْ اَنْ يُوصَفَ بِالوَجهِ وَلِكن مَعُناهُ كُلُّ شَى ءٍ هالِكٌ اِلاّ دينُهُ وَ الوَجْهُ الذّى يُؤتى مِنهُ. حديث","fa":"امام باقر علیه السلام درباره آیه« کل شی هالک الاّ وجهه»به ابوحمزه ثمالی فرمود: هر چیز نابود می شود و وجه باقی می ماند. خداوند بزرگ تر از آن است که وجه (چهره) داشته باشد و معنای آیه این است که همه چیز نابود می شود الاّ دین خدا و سمت و سویی که مردم از آن به سمت خدا رو می آورند.","at":"امام باقر (ع) — چهل حدیث «گهرهای باقری» (حدیث ۷۰۱)"},{"id":"d119","by":"baqir","ar":"اِنَّ بَعْضَ اَصَحْابِهِ سَأَلَهُ فَقالَ: جُعِلتُ فَدِاكَ اِنَّ الشّيعَهَ عِنْدَ ناكثيروُنَ، فَقالَ: هَلْ يَعْطِفُ الغَنِىُّ عَلى الفَقيرَ، وَ يَتَجاوَزُ المُحْسِنُ عَنْ المُسى ء وَ يَتَواسُونَ؟ قُلْتُ: لا، قالَ عليه السلام: لَيْسَ هؤُلاءِ الشّيعَةَ، الشَّيعَةُ مَنْ يَفْعَلُ هذا. حديث","fa":"یکی از یاران امام باقر علیه السلام به آن حضرت گفت: شیعیان در منطقه ما زیادند. حضرت فرمود: آیا توانگر آنان بر فقیر مهر می ورزد؟ و نیکوکار از بدکار می گذرد؟ و مواسات و بذل و بخشش مالی دارند؟ گفت: خیر. حضرت فرمود: اینان شیعه نیستند. شیعه کسی است که چنین باشد.","at":"امام باقر (ع) — چهل حدیث «گهرهای باقری» (حدیث ۷۰۲)"},{"id":"d120","by":"baqir","ar":"كُلُ عَيْنٍ باكِيَةٌ يَوْمَ القِيامَةِ اِلاّ ثَلاثَ عُيُونٍ: عَيْنٌ سَهَرَتْ فِى سَبيلِ اللّهِ. وَ عَيْنٌ فاضَت مِنْ خَشْيَةِ اللّهِ. وَ عَيْنٌ غَضَّتْ عَنْ مَحارِمِ اللّهِ. حديث","fa":"امام باقر علیه السلام فرمود: روز قیامت همه چشم ها گریان است مگر سه چشم: چشمی که در راه خدا بیدار مانده است، چشمی که از خوف خدا گریسته است، چشمی که از محارم الهی فرو بسته شده است.","at":"امام باقر (ع) — چهل حدیث «گهرهای باقری» (حدیث ۷۰۳)"},{"id":"d121","by":"baqir","ar":"تِسْعُ خِصالٍ خَصَّ اللّهُ بِها رُسُلَهُ فَاْمتَحِنُوا أنفُسَكُمْ فَإنْ كانت فَيكُمْ فَاحْمَدُوا اللّهَ تَعالى عَلَيْها فاْسَاَلُوُهُ فِيْها، وَ هُمُ: اليَقينُ وَ القَناعَةُ وَ الصَّبْرُ وَ الشُّكْرُ وَ الحِلْمُ وَ حُسْنُ الخُلْقِ وَ السَّخاءُ وَ الشَّجاعَةُ وَ التَّنَزُّهُ. حديث","fa":"امام باقر علیه السلام فرمود: نُه خصلت است که خداوند آن ها را از ویژگیهای پیامبرانش قرار داده است. پس خود را بیازمایید بنگرید اگر آنها را دارید، خدا را حمد و ستایش کنید و اگر ندارید از او بخواهید. آن ها عبارتند از: یقین، قناعت، صبر، شکر، حلم، حسن خلق، سخاوت، شجاعت، پاکیزگی و پارسایی.","at":"امام باقر (ع) — چهل حدیث «گهرهای باقری» (حدیث ۷۰۴)"},{"id":"d122","by":"baqir","ar":"مَنْ كَذَبَ ذَهَبَ جَمالُهُ، وَ مَنْ ساءَ خُلقُهُ عَذَّبَ نَفْسَهُ وَ كَثُرَتْ هُمُومُهُ وَتَظاهَرَ عَلَيْهِ الْنِّعمَةَ فَلْيُكْثِر مِنَ الشُّكْرِ، وَ مَنْ كَثُرَتْ هُمُومُهُ فَليُكثِرْ مِنْ الاِسْتِغفارِ، وَ مَنْ اَلَحَّ عَلَيْهِ الفَقرُ، فَليَقُلْ « لا حَولَ وَ لا قُوَّةَ إلاّ بِاللّهِ العَلِىّ العَظيمِ». حديث","fa":"امام باقر علیه السلام فرمود: هر کس دروغ بگوید آراستگی او برود، هر کس اخلاقش بد شود خود را عذاب می دهد و اندوهش فراوان می شود. هر کس نعمت ها پیایی بر او فرود آید، باید زیاد شکر کند. هر کس اندوهش زیاد شود، بسیار استغفار کند. و هر کس فقر بر او فشار آورد، بگوید: «لا حَولَ وَ لا قُوَّةَ إلاّ بِاللّه ِ العَلِی العَظیمِ».","at":"امام باقر (ع) — چهل حدیث «گهرهای باقری» (حدیث ۷۰۵)"},{"id":"d123","by":"baqir","ar":"ما مِنْ خُطْوَةٍ اَحَبُّ [إلَى] اللّهِ مِنْ خُطْوَتَينِ: خُطْوَةٌ تَشُدُّ صَفّاً فى سَبيلِ اللّهِ. وَ خُطْوَةٌ إلِى ذى رَحِمٍ قاطِعٍ وَ ما مِنْ جُرعَةٍ اَحَبُّ [الِىَّ] مِنْ جُرعَتَيْنِ: جُرْعَةُ غَيْظٍ رَدَّها مُؤمِنٌ بِحِلْمٍ وَ جُرعَةُ مُصيبَةٍ رَدَّها مُؤمِنٌ بِصَبْرٍ وَ ما مِنْ قَطْرَةٍ اَحَبُّ الِىَ اللّهِ مِنْ قَطْرَتَينِ: قَطْرَةُ دَمٍ فِى سَبيلِ اللّهِ وَقَطْرَةُ دَمْعٍ فِى سَوادِاللَّيلِ لايُريدُ بِها إلاَّاللّهَ عَزَّوَجَلَّ. حديث","fa":"امام باقر علیه السلام فرمود: دو گام است که از آن محبوب تر نزد خدا نیست: ۱. گامی به سوی جبهه ها برای تحکیم صف مجاهدان راه خدا. ۲. گامی به سوی خویشاوندی که پیوند خویش گسسته است. دو جرعه است که از آن محبوب تر نزد خدا نیست: ۱. جرعه ای از خشم که مؤمن آن را با حلم فرو برد. ۲. جرعه ای از مصیبت که با صبر آن را باز گرداند. و دو قطره است که از آن نزد خدا بهتر نیست: ۱. قطره ای خون در راه خدا، ۲. قطره ای اشک در سیاهی شب که جز برای خدا نیفشاند.","at":"امام باقر (ع) — چهل حدیث «گهرهای باقری» (حدیث ۷۰۶)"},{"id":"d124","by":"baqir","ar":"اَوحَى اللّهَ تَعالى الِى مُوسى عليه السلام: اِنّ مِنْ عِبادى مَنْ يَتَقَرَّبُ بِالحَسَنَةِ فَاُحكِمُهُ فِى الجَنَّةِ، فَقالَ مُوسى: يا رَبِّ ما تِلْكَ الحَسَنَةُ؟ قالَ: يَمْشى فِىحاجَةِ اَخيهِ المُؤمِن قُضِيَت اَوْ لَمْ تُقْضَ! حديث","fa":"امام باقر علیه السلام: فرمود: خداوند به موسی علیه السلام وحی کرد که: بعضی از بندگان من آن قدر کار نیک انجام می دهد که او را در بهشت حاکم و برقرار می سازم. موسی گفت: خدایا آن کار نیک چیست؟ فرمود: برای تأمین نیاز برادرش تلاش می کند، موفق به قضای حوائج او بشود یا نشود.","at":"امام باقر (ع) — چهل حدیث «گهرهای باقری» (حدیث ۷۰۷)"},{"id":"d125","by":"baqir","ar":"ثَلاثةٌ مِنْ أفْضَلِ الاَعْمالِ: شِبْعَةُ جُوْعَةِ المُسْلِمِ وَ تَنْفيسُ كُرْبَتِهِ وَ تَكْسُو عَوْرَتَهُ. حديث","fa":"امام باقر علیه السلام فرمود: سه چیز از برترین اعمال است: سیر کردن گرسنگی مسلمان، زدودن غم مسلمان، پوشاندن زشتی و عیب او.","at":"امام باقر (ع) — چهل حدیث «گهرهای باقری» (حدیث ۷۰۸)"},{"id":"d126","by":"baqir","ar":"لَوَ اَنَّ رَجُلاً اَحَبَّ رَجُلاً فِىاللّه لاََثابَهُ اللّهُ عَلى حُبِّهِ وَ اِنْ كانَ المَحْبُوبُ فِى عِلْمِ اللّهِ مِن اَهْلِ النّارِ وَلَوَاَنَّ رَجُلاً اَبَغَضَ رَجُلاً للّه ِِ لاََثابَهُ عَلى بُغْضِهِ اِيّاهُ، وَ اِنْ كانَ المُبْغَضُ فِى عِلْمِ اللّهِ مِنْ اَهْلِ الجَنَّةِ. حديث","fa":"امام باقر علیه السلام فرمود: اگر کسی مردی را در راه خدا دوست بدارد، خداوند به او پاداش محبتش را می دهد، گرچه آن شخص محبوب در علم الهی اهل آتش باشد و اگر کسی شخصی را در راه خدا دشمن بدارد، خداوند پاداش بغض و خشم او را می پردازد، گرچه شخص مورد خشم و نفرت در علم الهی از اهل بهشت باشد.","at":"امام باقر (ع) — چهل حدیث «گهرهای باقری» (حدیث ۷۰۹)"},{"id":"d127","by":"baqir","ar":"قالَ: تَبَسُّمُ الرَّجُلِ فِى وَجْهِ اَخيهِ حَسَنَةٌ وَ صَرْفُهُ القَذا عَنهُ حَسَنَةٌ وَ ما عُبِدَاللّهُ بِشَى ءٍ اَحَبُّ اِلَيْهِ مِنْ اِدْخالِ السُّرُورِ عَلى المُؤمِنِ. حديث","fa":"امام باقر علیه السلام فرمود: لبخند انسان به چهره برادرش حسنه و کار نیک است و دور کردن خار و خاشاک و رنج و گرفتاری از برادر دینی حسنه است و خداوند به چیزی بهتر از شاد کردن مؤمن عبادت نشده است.","at":"امام باقر (ع) — چهل حدیث «گهرهای باقری» (حدیث ۷۱۰)"},{"id":"d128","by":"sadiq","ar":"مَنْ بَدَءَ بِكَلامٍ قَبْلَ سَلامٍ فَلاتُجيبُوهُ. حديث","fa":"امام صادق علیه السلام فرمود: کسی که قبل از سلام سخن گوید، به او اعتنا نکنید.","at":"امام صادق (ع) — چهل حدیث «گهرهای صادقی» (حدیث ۸۰۱)"},{"id":"d129","by":"sadiq","ar":"صَلاحُ حالِ التَّعايُشِ وَالتَّعاشُرِ مِلْ ءُ مِكْيالٍ ثُلْثاهُ فِطْنَةٌ وَثُلْثُهُ تَغافُلٌ. حديث","fa":"امام صادق علیه السلام فرمود: اصلاح زندگانی فردی و معاشرت اجتماعی پیمانه پُری است که دو سومش زیرکی و یک سومش چشم پوشی است.","at":"امام صادق (ع) — چهل حدیث «گهرهای صادقی» (حدیث ۸۰۲)"},{"id":"d130","by":"sadiq","ar":"اِذا صَلُحَ اَمْرُدُنْياكَ فَاتَّهِمْ دينَكَ. حديث","fa":"امام صادق علیه السلام فرمود: هر گاه کار دنیایت به سامان شد، دینت را متهم ساز. (مواظب باش دینت آسیب ندیده باشد.)","at":"امام صادق (ع) — چهل حدیث «گهرهای صادقی» (حدیث ۸۰۳)"},{"id":"d131","by":"sadiq","ar":"لاتَنْظُرُوا في عُيُوبِ النّاسِ كَالْأرْبابِ وَانْظُرُوا في عُيُوبِكُمْ كَهَيْئَةِ الْعَبْدِ. حديث","fa":"امام صادق علیه السلام فرمود: ارباب گونه به عیوب دیگران ننگرید، بلکه چون بنده ای متواضع، عیب های خود را وارسی کنید.","at":"امام صادق (ع) — چهل حدیث «گهرهای صادقی» (حدیث ۸۰۴)"},{"id":"d132","by":"sadiq","ar":"ثَلاثٌ مَنْ كُنَّ فيهِ فَهُوَ مُنافِقٌ وَاِنْ صامَ وَصَلّى: مَنْ اِذا حَدَّثَ كَذِبَ وَاِذا وَعَدَ اَخْلَفَ وَ اِذَا ائْتُمِنَ خانَ. حديث","fa":"امام صادق علیه السلام فرمود: سه خصلت علامت نفاق است، گر چه صاحبش اهل نماز و روزه باشد: دروغگویی، خلف وعده و خیانت در امانت.","at":"امام صادق (ع) — چهل حدیث «گهرهای صادقی» (حدیث ۸۰۵)"},{"id":"d133","by":"sadiq","ar":"اِزالَةُ الْجِبالِ اَهْوَنُ مِنْ اِزالَةِ قَلْبٍ عَنْ مَوْضِعِهِ. حديث","fa":"امام صادق علیه السلام فرمود: کوه کندن از دل کندن آسانتر است.","at":"امام صادق (ع) — چهل حدیث «گهرهای صادقی» (حدیث ۸۰۶)"},{"id":"d134","by":"sadiq","ar":"اِيّاكُمْ اَنْ يَحْسُدَ بَعْضُكُمْ بَعْضا فَاِنَّ الْكُفْرَ اَصْلُهُ الْحَسَدُ. حديث","fa":"امام صادق علیه السلام فرمود: مبادا با یکدیگر حسد ورزید، زیرا کفر و بی دینی از حسد بر می خیزد.","at":"امام صادق (ع) — چهل حدیث «گهرهای صادقی» (حدیث ۸۰۷)"},{"id":"d135","by":"sadiq","ar":"اَرْبَعَةُ اَشْياءٍ اَلْقَليلُ مِنْها كَثيرٌ: الَنّارُ وَالْعَداوَةُ وَالْفَقْرُ وَالْمَرَضُ. حديث","fa":"امام صادق علیه السلام فرمود: چهار چیز است که اندک آن هم بسیار است: آتش، دشمنی، فقر و بیماری.","at":"امام صادق (ع) — چهل حدیث «گهرهای صادقی» (حدیث ۸۰۸)"},{"id":"d136","by":"sadiq","ar":"مَنْ كَشَفَ حِجابَ غَيْرِهِ اِنْكَشَفَتْ عَوْراتُ بَيْتِهِ. حديث","fa":"امام صادق علیه السلام فرمود: هر که پرده دری کند، اسرار و عیوبِ خانه خودش آشکار می شود.","at":"امام صادق (ع) — چهل حدیث «گهرهای صادقی» (حدیث ۸۰۹)"},{"id":"d137","by":"sadiq","ar":"إخْتَبِرُوا إخْوانَكُمْ بِخَصْلَتَينِ: فَإنْ كانَتا فيهِمْ وَإلاّ فَأعْزُبْ ثُمَّ اَعْزُبْ ثُمَّ أعْزُبْ: ألْمُحافَظَةُ عَلَى الصَّلَواتِ فى مَواقيتِها وَالبِرُّ بِالإخْوانِ فِى العُسْرِ وَاليُسْرِ. حديث","fa":"امام صادق علیه السلام فرمود: برادران خود را با دو صفت امتحان کنید، که اگر آن دو صفت را داشتند به دوستی و رفاقت خود با آنها ادامه دهید وگرنه از آنان دوری کنید، دوری کنید، دوری کنید: ۱ مراقبت بر نماز اول وقت. ۲ نیکی به برادران چه در سختی وتنگدستی، چه درهنگام آسایش وگشایش.","at":"امام صادق (ع) — چهل حدیث «گهرهای صادقی» (حدیث ۸۱۰)"},{"id":"d138","by":"kazim","ar":"اِنَّ اَبْدانَكم لَيْسَ لَها ثَمَنٌ اِلاَّ الْجَنَّةُ، فَلاتَبيعُوها بِغَيْرِها. حديث","fa":"امام کاظم علیه السلام فرمود: همانا بدنهای شما را بهایی جز بهشت نیست. پس آنرا به غیر بهشت نفروشید.","at":"امام کاظم (ع) — چهل حدیث «گهرهای کاظمی» (حدیث ۹۰۱)"},{"id":"d139","by":"kazim","ar":"اَلْمَغْبُونُ مَن غَبَنَ مِنْ عُمْرِهِ ساعَةً. حديث","fa":"امام کاظم علیه السلام فرمود: زیانکار، کسی است که ساعتی از عمر خویش را باخته است.","at":"امام کاظم (ع) — چهل حدیث «گهرهای کاظمی» (حدیث ۹۰۲)"},{"id":"d140","by":"kazim","ar":"تَفَقَّهُوا فى دينِ اللّهِ، فَإنَّ الْفِقْهَ مِفْتاحُ الْبَصيرَةِ وَتَمامُ الْعِبادَةِ. حديث","fa":"امام کاظم علیه السلام فرمود: در دین خدا دانا شوید، همانا دین شناسی و فقه، کلید بصیرت و کمال عبادت است.","at":"امام کاظم (ع) — چهل حدیث «گهرهای کاظمی» (حدیث ۹۰۳)"},{"id":"d141","by":"kazim","ar":"مَنْ بَذَّرَ وَاَسْرَفَ زالَتْ عَنْهُ النِّعْمَةُ. حديث","fa":"از امام کاظم علیه السلام روایت است: هرکس ولخرجی و اسراف کند، نعمت از دستش می رود.","at":"امام کاظم (ع) — چهل حدیث «گهرهای کاظمی» (حدیث ۹۰۴)"},{"id":"d142","by":"kazim","ar":"مَنْ وَلَّدَهُ الْفَقْرُ اَبْطَرَهُ الْغِنى. حديث","fa":"امام موسی بن جعفر علیه السلام فرمود: کسی که زاده فقر باشد، ثروتمندی او را به طغیان و سرمستی می کشد.","at":"امام کاظم (ع) — چهل حدیث «گهرهای کاظمی» (حدیث ۹۰۵)"},{"id":"d143","by":"kazim","ar":"وَجَدْتُ عِلْمَ النّاسِ فى اَرْبَعٍ: اَوَّلُها اَنْ تَعْرِفَ رَبَّكَ، وَالثّانِيَةُ اَنْ تَعْرِفَ ما صَنَعَ بِكَ، وَالثّالِثَةُ اَنْ تَعْرِفَ ما اَرادَ مِنْكَ، وَالرّابِعَةُ اَنْ تَعْرِفَ ما يُخْرِجُكَ مِنْ دينِكَ. حديث","fa":"امام کاظم علیه السلام فرمود: دانش مردم را در چهار چیز یافتم: اوّل: آنکه پروردگارت را بشناسی، دوم: آنکه بدانی با تو و برای تو چه کرده است، سوم: آنکه بدانی از تو چه خواسته است، چهارم: آنکه بدانی چه چیز تو را از دینت بیرون می کند.","at":"امام کاظم (ع) — چهل حدیث «گهرهای کاظمی» (حدیث ۹۰۶)"},{"id":"d144","by":"kazim","ar":"اِذا كانَ ثَلاثَةٌ فى بَيْتٍ فَلايَتَناجىَ اثنانِ دُونَ صاحِبِهِما، فَإنَّ ذالِكَ مِمّا يَغُمُّهُ. حديث","fa":"امام کاظم علیه السلام فرمود: هر گاه سه نفر در خانه ای هستند، دو نفرشان جدا از رفیق خود، نجوا و صحبتِ درگوشی نکنند، چرا که این کار، او را اندوهگین می سازد.","at":"امام کاظم (ع) — چهل حدیث «گهرهای کاظمی» (حدیث ۹۰۷)"},{"id":"d145","by":"kazim","ar":"مَثَلُ الدُّنْيا مَثَلُ ماءِ الْبَحْرِ كُلَّما شَرِبَ مِنْهُ الْعَطْشانُ ازْدادَ عَطَشا حَتّى يَقْتُلَهُ. حديث","fa":"از وصایای امام کاظم علیه السلام به هشام: مَثَل دنیا، همچون آب دریاست (که شور است). تشنه هر چه از آن بنوشد، تشنه تر می شود، تا آنکه او را می کشد.","at":"امام کاظم (ع) — چهل حدیث «گهرهای کاظمی» (حدیث ۹۰۸)"},{"id":"d146","by":"kazim","ar":"بِئْسَ الْعَبْدُ عَبْدٌ يَكُونُ ذا وَجْهَيْنِ وَذا لِسانَيْنِ يُطْرى اَخاهُ اِذا شاهَدَهُ وَيَأْكُلُهُ اِذا غابَ عَنْهُ. حديث","fa":"از سخنان امام کاظم علیه السلام: بد بنده ای است، بنده ای که دورو و دوزبان است، هرگاه برادر دینی اش را می بیند، او را می ستاید و تملّق می گوید و پشت سرش (بابدگویی) او را می خورد!","at":"امام کاظم (ع) — چهل حدیث «گهرهای کاظمی» (حدیث ۹۰۹)"},{"id":"d147","by":"kazim","ar":"اَلْمُصيبَةُ لِلصّابِرِ واحِدَةٌ وَلِلْجازِعِ اثنَتانِ. حديث","fa":"امام کاظم علیه السلام فرمود: مصیبت، برای انسان شکیبا یکی است و برای بی تابی کننده دو تا می شود!","at":"امام کاظم (ع) — چهل حدیث «گهرهای کاظمی» (حدیث ۹۱۰)"},{"id":"d148","by":"reza","ar":"لا يَسْتَكْمِلُ عَبْدٌ حَقيقَةَ الايمانِ حَتّى تَكُونَ فيهِ خِصالٌ ثَلاثٌ: اَلتَفَقُّهُ فىالدّينِ، وَ حُسْنُ التَّقْديرِ فِى الْمَعيشَةِ وَالصَّبْرُ عَلَى الرَّزايا. حديث","fa":"امام رضا علیه السلام فرمود: هیچ بنده ای به کمال حقیقی ایمان نمی رسد، تا اینکه این سه خصلت در او باشد: دین شناسی. اندازه و برنامه ریزی در زندگی. شکیبایی بر سختیها و ناملایمات.","at":"امام رضا (ع) — چهل حدیث «گهرهای رضوی» (حدیث ۱۰۰۱)"},{"id":"d149","by":"reza","ar":"اَلاْءيمانُ هُوَ مَعْرِفَةٌ بِالْقَلْبِ وَ اِقْرارٌ بِالّلِسانِ وَ عَمَلٌ بِالْأرْكانِ. حديث","fa":"امام رضا علیه السلام فرمود: ایمان عبارت است از: شناخت قلبی، اعتراف زبانی، عمل با اعضاء وجوارح","at":"امام رضا (ع) — چهل حدیث «گهرهای رضوی» (حدیث ۱۰۰۲)"},{"id":"d150","by":"reza","ar":"اَلْمُؤمِنُ اِذا غَضِبَ لَمْ يُخْرِجْهُ غَضَبُهُ عَنْ حَقٍّ، وَ اِذا رَضِىَ لَمْ يُدْخِلْهُ رِضاهُ فى باطِلٍ، وَ اِذا قَدَرَ لَمْ يَأْخُذْ اَكْثَرَ مِنْ حَقِّهِ. حديث","fa":"امام رضا علیه السلام فرمود: مؤمن، هرگاه خشمگین شود، غضبش او را از حق بیرون نمی برد و هرگاه خرسند شود، خوشنودیش او را به باطل نمی کشاند و هرگاه قدرت یابد، بیش از حق خودش بر نمی دارد.","at":"امام رضا (ع) — چهل حدیث «گهرهای رضوی» (حدیث ۱۰۰۳)"},{"id":"d151","by":"reza","ar":"لايُحِبُّنا كافِرٌ وَلا يُبْغِضُنا مُؤْمِنٌ، وَ مَنْ ماتَ وَهُوَ يُحِبُّنا كانَ عَلَى اللّهِ حَقّا اَنْ يَبْعَثَهُ مَعَنا. حديث","fa":"امام هشتم علیه السلام فرمود: هیچ کافری ما را دوست نمی دارد و هیچ مؤمنی دشمن ما نمی شود. هرکس با محبّت ما اهل بیت بمیرد، بر خداوند حتمی است که او را در قیامت با ما برانگیزد.","at":"امام رضا (ع) — چهل حدیث «گهرهای رضوی» (حدیث ۱۰۰۴)"},{"id":"d152","by":"reza","ar":"اِنَّ الإمامَةَ زِمامُ الدّينِ وَ نِظامُ الْمُسْلِمينَ وَ صَلاحُ الدُّنيا وَ عِزُّ الْمُؤْمِنينَ. حديث","fa":"امام رضا علیه السلام فرمود: امامت و رهبری، رشته داری دین و نظام بخشی مسلمانان است و موجب اصلاح دنیا و عزّت و سربلندی مؤمنان است.","at":"امام رضا (ع) — چهل حدیث «گهرهای رضوی» (حدیث ۱۰۰۵)"},{"id":"d153","by":"reza","ar":"اِنَّ زُوّارَ قَبْرى لَأَكْرَمُ الْوُفُودِ عَلَى اللّهِ يَوْمَ الْقِيامَةِ، وَ ما مِنْ مُؤْمِنٍ يَزُورُنى فَيُصيبُ وَجْهَهُ مِنَ الْماءِ اِلاّ حَرَّمَ اللّهُ تَعالى جَسَدَهُ عَلَى النّارِ. حديث","fa":"امام رضا علیه السلام فرمود: زائران قبرم از گرامی ترین گروههایی اند که روز قیامت، بر خدا وارد می شوند. هیچ مؤمنی نیست که مرا زیارت کند و در راه زیارتم بر چهره اش قطره آبی بچکد، مگر آنکه خدای متعال، بدن او را بر آتش دوزخ حرام می کند.","at":"امام رضا (ع) — چهل حدیث «گهرهای رضوی» (حدیث ۱۰۰۶)"},{"id":"d154","by":"reza","ar":"حُبُّ اَوْلِياءِ اللّهِ واجِبٌ وَ كَذلِكَ بُغْضُ اَعْدائِهِمْ وَ الْبَرائَةُ مِنْهُمْ وَ مِنْ اَئِمَّتِهِمْ. حديث","fa":"امام رضا علیه السلام در نوشته خود به مأمون، فرموده است: دوستی با دوستان خدا واجب است، همچنین دشمن داشتن و بیزاری جستن از دشمنان دوستان خدا و سران آنان واجب است.","at":"امام رضا (ع) — چهل حدیث «گهرهای رضوی» (حدیث ۱۰۰۷)"},{"id":"d155","by":"reza","ar":"مَنْ لَمْ يَقْدِرْ عَلى زِيارَتِنا فَلْيَزُرْ صالِحى مَوالينا يُكْتَبْ لَهُ ثَوابُ زِيارَتِنا. حديث","fa":"از امام رضا علیه السلام روایت است: هرکس نتواند ما را زیارت کند، دوستان و پیروان شایسته ما را زیارت کند، تا پاداش زیارت ما برایش نوشته شود.","at":"امام رضا (ع) — چهل حدیث «گهرهای رضوی» (حدیث ۱۰۰۸)"},{"id":"d156","by":"reza","ar":"اَلَّذينَ اِذا اَحْسَنُوا اسْتَبْشَرُوا، وَاِذا اَساؤُوا اسْتَغْفَرُوا، وَ اِذا اُعْطُوا شَكَرُوا، وَ اِذَا ابْتَلَوْا صَبَرُوا، وَ اِذا غَضِبُوا عَفَوا. حديث","fa":"از حضرت رضا علیه السلام درباره بهترین بندگان پرسیدند. حضرت فرمود: آنان که هرگاه نیکی می کنند، خوشحال می شوند، هرگاه بدی می کنند، استغفار می کنند، هرگاه چیزی به آنان داده می شود، سپاس می گویند، هرگاه مبتلا و گرفتار می شوند، شکیبایی می کنند، و هرگاه خشمگین می شوند، عفو و گذشت می کنند.","at":"امام رضا (ع) — چهل حدیث «گهرهای رضوی» (حدیث ۱۰۰۹)"},{"id":"d157","by":"reza","ar":"اِنَّ اَبَاالحَسَنِ عليه السلام سُئِلَ عَنْ اَفْضَلِ عَيْشِ الدُّنْيا، فَقالَ: سِعَةُ الْمَنْزِلِ وَ كَثْرَةُ الْمُحِبّينَ. حديث","fa":"از حضرت رضا علیه السلام پرسیدند: بهترین خوشی و لذّت دنیا چیست؟ فرمود: خانه وسیع و بسیاری دوستان.","at":"امام رضا (ع) — چهل حدیث «گهرهای رضوی» (حدیث ۱۰۱۰)"},{"id":"d158","by":"jawad","ar":"اَلْقَصْدُ اِلىَ اللّهِ تَعالى بِالْقُلُوبِ اَبْلَغُ مِنِ اتْعابِ الْجَوارِحِ بِالْأعْمالِ. حديث","fa":"امام جواد علیه السلام فرمود: توجه قلبی به خدا، رساتر است از زحمت دادن اعضاء و جوارح به عمل.","at":"امام جواد (ع) — چهل حدیث «گهرهای تقوی» (حدیث ۱۱۰۱)"},{"id":"d159","by":"jawad","ar":"الثِّقَةُ بِاللّهِ ثَمَنٌ لِكُلِّ غالٍ وَسُلَّمٌ اِلى كُلِّ عالٍ. حديث","fa":"امام محمد تقی علیه السلام فرمود: اطمینان و توکل بر خدا بهای هر چیز گرانقیمت و نردبان هر مقام بالا و رفیعی است.","at":"امام جواد (ع) — چهل حدیث «گهرهای تقوی» (حدیث ۱۱۰۲)"},{"id":"d160","by":"jawad","ar":"إذا نَزَلَ الْقَضاءُ ضاقَ الْفَضاءُ. حديث","fa":"امام جواد علیه السلام فرمود: آنگاه که قضای الهی فرا رسد، فضا هم بر انسان تنگ می شود.","at":"امام جواد (ع) — چهل حدیث «گهرهای تقوی» (حدیث ۱۱۰۳)"},{"id":"d161","by":"jawad","ar":"اِنَّ أنْفُسَنا وَأَمْوالَنا مِنْ مَواهِبِ اللّهِ ألْهَنيئَةِ وَعواريهِ المُسْتَوْدَعَةِ يُمَتِّعُ بِما مَتَّعَ مِنْها فيسُرُورٍ وَغِبْطَةٍ وَيَأخُذُ ما اَخَدَ مِنْها فى اَجْرٍ و حِسْبَةٍ. فَمَنْ غَلَبَ جَزَعُهُ عَلى صَبْرِهِ حَبِطَ أَجْرُهُ وَنَعُوذُ بِاللّهِ مِنْ ذلِكَ. حديث","fa":"امام محمد تقی علیه السلام فرمود: همانا جانها و مالهایمان از موهبتهای گوارا و امانتهای سپرده خداوند است، هر چه بخواهد، با خوشحالی وخرسندی از آنها بهره مندمان می گرداند، و هر چه را که بخواهد، با دادن ثواب و پاداش می گیرد، آنکه بی تابیش بر تحمل و استقامت وی افزون شود، اجر او از بین رفته است و از این حالت به خدا پناه می بریم.","at":"امام جواد (ع) — چهل حدیث «گهرهای تقوی» (حدیث ۱۱۰۴)"},{"id":"d162","by":"jawad","ar":"لاتَكُنْ وَليّا لِلّهِ فىِ الْعَلانِيّةِ، عَدُوّا لَهُ فِى السِّرِ. حديث","fa":"امام جواد علیه السلام فرمود: اینگونه مباش که در ظاهر با خدا دوستی کنی و در پنهانی دشمنی","at":"امام جواد (ع) — چهل حدیث «گهرهای تقوی» (حدیث ۱۱۰۵)"},{"id":"d163","by":"jawad","ar":"اَلْمُؤمِنُ يَحْتاجُ اِلى تَوْفيقٍ مِنَ اللّهِ وَواعِظٍ مِنْ نَفْسِهِ وَقَبُولٍ مِمَّنْ يَنْصَحُهُ. حديث","fa":"امام محمد تقی علیه السلام فرمود: مؤمن به سه چیز محتاج است: ۱ توفیق الهی، که کارها را بخوبی به پیش ببرد. ۲ واعظ درونی که هرلحظه او را پند و انذار دهد. ۳ پذیرش نصحیت کسی که او را پند می دهد.","at":"امام جواد (ع) — چهل حدیث «گهرهای تقوی» (حدیث ۱۱۰۶)"},{"id":"d164","by":"jawad","ar":"اَوْحَى اللّهُ اِلى بَعْضِ الأنبِياءِ: أمّا زُهْدُكَ في الدُّنيا فَتُعَجِّلُكَ الرّاحَةَ وَامّا انْقِطاعُكَ اِلىَّ فَيُعَزِّزُكَ بي، وَلكِنْ هَلْ عادَيْتَ لي عَدُوّا وَ والَيْتَ لي وَليّا. حديث","fa":"امام محمد تقی علیه السلام فرمود: خداوند به یکی از پیامبران وحی کرد: امّا زُهد تو، آسایشی را به دنبال دارد که به زودی به تو خواهد رسید، امّا جدایی از دیگران و پیوستنت به من، تو را عزیز خواهد کرد، (اینها برای خودت بود) امّا آیا برای من با دشمنم دشمنی کردی؟ و با دوستم رفاقت کردی؟","at":"امام جواد (ع) — چهل حدیث «گهرهای تقوی» (حدیث ۱۱۰۷)"},{"id":"d165","by":"jawad","ar":"عَلِّمِنى شَيْئا إذا أنَا قُلْتُهُ كُنْتُ مَعَكُمْ فِى الدُّنيا وَالآخِرةِ، قالَ: فَكَتَبَ بِخَطِّهِ أَعْرِفْهُ: اَكْثِرْ مِنْ تِلاوَةِ «إنّا أنزَلْناهُ» وَرَطِّبْ شَفَتَيْكَ بِالأسْتِغْفارِ. حديث","fa":"اسماعیل بن سهل گوید: خدمت امام جواد علیه السلام نوشتم، چیزی به من تعلیم فرما که اگر آن را بگویم (بخوانم) در دنیا و آخرت با شما باشم. حضرت به خط خود نوشت: سوره «انا انزالناه» را زیاد بخوان و لبهایت به گفتن استغفار « تر» باشد، (یعنی آنقدر استغفار کُنی که هیچگاه لبت خشک نشود).","at":"امام جواد (ع) — چهل حدیث «گهرهای تقوی» (حدیث ۱۱۰۸)"},{"id":"d166","by":"jawad","ar":"ما عَظُمَتْ نِعَمُ اللّهِ عَلى اَحَدٍ إلاّ عَظُمَتْ إلَيْهِ حوائِجُ النّاسِ فَمَنْ لَمْ يَحْتَمِلْ تِلْكَ الْمَعُونَةَ عَرَّضَ تِلْكَ النِّعمَةَ لِلزَّوالِ. حديث","fa":"امام جواد علیه السلام فرمود: عظمت و بزرگی نعمتهای الهی بر کسی معلوم نمی شود مگر آنکه مردم از او درخواستهای بزرگی بکنند و هر کس این سخن (درخواستهای مردم) را تحمل نکند، (پاسخ نگوید) آن نعمت خداوندی را در معرض نابودی قرار داده است.","at":"امام جواد (ع) — چهل حدیث «گهرهای تقوی» (حدیث ۱۱۰۹)"},{"id":"d167","by":"jawad","ar":"اَلدّينُ عِزٌّ وَالْعِلمُ كَنزٌ وَالصَّمْتُ نُورٌ وَغايَةُ الزُّهدِ ألوَرَعُ وَلاهَدْمَ لِلدّينِ مِثْلُ الْبِدَعَ وَلااَفسَدَ لِلرَّجُلِ مِنَ الطَّمَعِ وَبِالرّاعى تَصْلِحُ الرَّعِيَّةُ وَبِالدُّعاءِ تُصْرَفُ الْبَلِيَّةُ. حديث","fa":"امام جواد علیه السلام فرمود: دین سرفرازی است، و دانش، گنج است، و سکوت نوری است، و نهایت زهد پاکدامنی است، و هیچ چیز مثل بدعت دین را از بین نمی برد، و هیچ چیز مثل طمع مرد را تباه نمی کند، و به واسطه رؤساء مردم هم اصلاح می شوند، و بلا به وسیله دعا بر طرف می گردد.","at":"امام جواد (ع) — چهل حدیث «گهرهای تقوی» (حدیث ۱۱۱۰)"},{"id":"d168","by":"hadi","ar":"لاْتَعْدُ وَلاتَجْعَلْ لِلأيّامِ صُنْعا فىحُكْمِ اللّهِ. حديث","fa":"امام هادی علیه السلام فرمود: از حدّ خود تجاوز نکن و روزگار را در کار خدا دخیل مدان.","at":"امام هادی (ع) — چهل حدیث «گهرهای نقوی» (حدیث ۱۲۰۱)"},{"id":"d169","by":"hadi","ar":"مَنْ اَطاعَ الخالِقَ لَمْ يُبالِ سَخَطَ المَخْلُوقينَ وَمَنْ اَسْخَطَ الخالِقَ فَلْيَيْقَنْ اَنْ يَحِّلَ بِهِ سَخَطُ المَخْلُوقينَ. حديث","fa":"امام هادی علیه السلام فرمود: کسی که از آفریدگار پیروی کند از خشم آفریده ها باکی ندارد. و کسی که خدا را به خشم آورد، باید باور کند که مردم بر او خشم خواهند آورد.","at":"امام هادی (ع) — چهل حدیث «گهرهای نقوی» (حدیث ۱۲۰۲)"},{"id":"d170","by":"hadi","ar":"اَبْقُوا النِّعَمَ بِحُسْنِ مُجاوَرَتِها وَالْتَمِسوُا الزِيّادَةَ فيها بِالشُّكرِ عَلَيها. حديث","fa":"امام هادی علیه السلام فرمود: نعمتها را با برخورد درست، باقی نگه دارید و با شکر نعمتها اسباب فزونی آنها را فراهم آورید. (استفاده درست از نعمت سبب دوام آن و شکر نعمت سبب فزونی آن است).","at":"امام هادی (ع) — چهل حدیث «گهرهای نقوی» (حدیث ۱۲۰۳)"},{"id":"d171","by":"hadi","ar":"اِنَّ اللّهَ اِذا أَرادَ بِعَبْدٍ خَيرا إذا عُوتِبَ قَبِلَ. حديث","fa":"امام هادی علیه السلام فرمود: اگر خداوند خیر کسی را بخواهد، چنان می شود که هرگاه مورد توبیخ قرار گیرد، می پذیرد.","at":"امام هادی (ع) — چهل حدیث «گهرهای نقوی» (حدیث ۱۲۰۴)"},{"id":"d172","by":"hadi","ar":"الغِنى قِلَِّةُ ما تَمَنّيكَ وَالرِّضا بما يَكْفيكَ. حديث","fa":"امام هادی علیه السلام فرمود: بی نیازی، در کمی آرزو و رضایت به چیزی است که تو را کفایت می کند.","at":"امام هادی (ع) — چهل حدیث «گهرهای نقوی» (حدیث ۱۲۰۵)"},{"id":"d173","by":"hadi","ar":"إنَّ مِنَ الغِرَّةِ بِاللّهِ أنْ يُصِرَّ العَبدُ عَلَى المَعصِيَةِ وَ يِتَمَنّى عَلَى اللّهِ المَغفِرَةَ. حديث","fa":"امام هادی علیه السلام فرمود: از نشانه های غرور نسبت به خدا آن است که بنده، استمرار و اصرار بر گناه داشته باشد و در همان حال، آرزومند بخشایش الهی باشد.","at":"امام هادی (ع) — چهل حدیث «گهرهای نقوی» (حدیث ۱۲۰۶)"},{"id":"d174","by":"hadi","ar":"مَنْ هانَتْ عَلَيْهِ نَفسُهُ فَلا تَأْمَنْ شَرَّهُ. حديث","fa":"امام علی النقی علیه السلام فرمود: هر کس قدر خودش را نداند (ودر نظر خودش بی مقدار باشد) از شرّش ایمن مباش.","at":"امام هادی (ع) — چهل حدیث «گهرهای نقوی» (حدیث ۱۲۰۷)"},{"id":"d175","by":"hadi","ar":"أَلدُّنيا سُوقٌ رَبِحَ فيها قَوْمٌ وَ خَسِرَ آخَرُونَ. حديث","fa":"امام علی النقی علیه السلام فرمود: دنیا بازاری است که جمعی درآن سود می برند وگروهی زیان می بینند.","at":"امام هادی (ع) — چهل حدیث «گهرهای نقوی» (حدیث ۱۲۰۸)"},{"id":"d176","by":"hadi","ar":"اَلنّاسُ فِي الدُّنيا بِالْأَموالِ وَفىِ الاْخِرَةِ بِالاَْعمالِ. حديث","fa":"امام هادی علیه السلامفرمود: ارزش مردم در دنیا وابسته به اموال است، و در آخرت به اعمال.","at":"امام هادی (ع) — چهل حدیث «گهرهای نقوی» (حدیث ۱۲۰۹)"},{"id":"d177","by":"hadi","ar":"اِنَّ الظّالِمَ الْحالِمَ يَكادُ اَنْ يُعْفى عَلى ظُلْمِهِ بِحِلْمِهِ وَإنَّ الْمُحِقَّ السَّفيهَ يَكادُ اَنْ يُطْفِى ءَ نُورَحَقِّهِ بِسَفَهِهِ. حديث","fa":"امام هادی علیه السلام فرمود: ظالم بردبار (خردمند) ممکن است که با بردباری خود مورد عفو و گذشت از ظلمش قرار گیرد، ولی حق دارِ نادان، ممکن است، به سبب سفاهتش نور حقش را خاموش کند.","at":"امام هادی (ع) — چهل حدیث «گهرهای نقوی» (حدیث ۱۲۱۰)"},{"id":"d178","by":"askari","ar":"مِنَ التَواضُعِ السَّلامُ عَلى كُلِّ مَنْ تَمُرُّ بِهِ، وَ الْجُلُوسُ دُونَ شَرَفِ الْمَجْلِسِ. حديث","fa":"امام عسکری علیه السلام فرمود: سلام کردن به هر کس که بر او می گذری ونشستن در جایی که پایین تر از جایگاه (توست) نشانه تواضع و فروتنی است.","at":"امام حسن عسکری (ع) — چهل حدیث «گهرهای عسکری» (حدیث ۱۳۰۱)"},{"id":"d179","by":"askari","ar":"مَنْ رَضِىَ بِدُونِ الشَّرَفِ مِنَ المَجْلِسِ لَمْ يَزَلِ اللّهُ وَمَلائِكَتُهُ يُصَلُّونَ عَلَيْهِ حَتّى يَقُومَ. حديث","fa":"امام عسکری علیه السلام فرمود: کسی که در مجلس به پایین تر از جایگاه خود راضی شود، همواره خدا و فرشتگان الهی بر او درود می فرستند تا وقتی که برخیزد.","at":"امام حسن عسکری (ع) — چهل حدیث «گهرهای عسکری» (حدیث ۱۳۰۲)"},{"id":"d180","by":"askari","ar":"قَلْبُ الاَْحْمَقِ فى فَمِهِ وَ فَمُ الْحَكيمِ فى قَلْبِهِ. حديث","fa":"امام عسکری علیه السلام فرمود: قلب و دل احمق در دهان اوست و دهان انسان حکیم در (اختیار) قلب اوست. (یعنی انسان نادان نسنجیده حرف می زند وانسان خردمند وحکیم پس از اندیشه صحبت می کند.)","at":"امام حسن عسکری (ع) — چهل حدیث «گهرهای عسکری» (حدیث ۱۳۰۳)"},{"id":"d181","by":"askari","ar":"جُرأَةُ الْوَلَدِ عَلى والِدِهِ فى صِغَرِهِ تَدْعُو إلَى العُقُوقِ فى كِبَرِهِ. حديث","fa":"امام عسکری علیه السلام فرمود: پررویی و گستاخی فرزند در مقابل پدر در کودکی موجب نافرمانی و آزار او در بزرگی می شود.","at":"امام حسن عسکری (ع) — چهل حدیث «گهرهای عسکری» (حدیث ۱۳۰۴)"},{"id":"d182","by":"askari","ar":"حُسْنُ الصُّورَةِ جَمالٌ ظاهِرٌ، وَ حَسْنُ الْعَقْلِ جَمالٌ باطِنٌ. حديث","fa":"امام عسکری علیه السلام فرمود: زیبایی چهره، زیبایی ظاهری است و خوبی اندیشه زیبایی باطنی است.","at":"امام حسن عسکری (ع) — چهل حدیث «گهرهای عسکری» (حدیث ۱۳۰۵)"},{"id":"d183","by":"askari","ar":"مَنْ كانَ الْوَرَعُ سَجيَّتَهُ، وَ الْكَرَمُ طَبيعَتَهُ، وَ الْحِلْمُ خُلَّتَهُ، كَثُرَ صَديقُهُ وَ الثَّناءُ عَلَيْهِ، وَ انْتَصَرَ مِنْ أَعْدائِهِ بِحُسْنِ الثَّناءِ عَلَيْهِ. حديث","fa":"امام عسکری علیه السلام فرمود: کسی که پارسایی جزء سرشت او وجود و سخاوت جزء طبیعت او و بردباری دوست او گردد دوستانش و تعریف او زیاد خواهد شد و از دشمنانش با ستایش کردن بر او انتقام می گیرد.","at":"امام حسن عسکری (ع) — چهل حدیث «گهرهای عسکری» (حدیث ۱۳۰۶)"},{"id":"d184","by":"askari","ar":"لايَعْرِفُ النِّعْمَةَ اِلاَّ الشاكِرُ، وَ لا يَشْكُرُ النِّعْمَةَ اِلاَّ الْعارِفُ. حديث","fa":"امام عسکری علیه السلام فرمود: نعمت را جز سپاسگزار کسی نمی شناسد و جز عارف و دانا نعمت را سپاسگزاری نمی کند.","at":"امام حسن عسکری (ع) — چهل حدیث «گهرهای عسکری» (حدیث ۱۳۰۷)"},{"id":"d185","by":"askari","ar":"خِصْلَتانِ لَيْسَ فَوْقَهُما شَيْءٌ: أَلايمانُ بِاللّهِ وَ نَفْعُ الإخوانِ. حديث","fa":"امام عسکری علیه السلام فرمود: دو خصلت است که بالاتر از آنها چیزی نیست: ۱ ایمان به خدا ۲ سود رسانی به برادران دینی.","at":"امام حسن عسکری (ع) — چهل حدیث «گهرهای عسکری» (حدیث ۱۳۰۸)"},{"id":"d186","by":"askari","ar":"اَلْغَضَبُ مِفتاحُ كُلِّ شَرٍّ. حديث","fa":"امام عسکری علیه السلام فرمود: خشم، کلید هر بدی و زشتی است.","at":"امام حسن عسکری (ع) — چهل حدیث «گهرهای عسکری» (حدیث ۱۳۰۹)"},{"id":"d187","by":"askari","ar":"جُعِلَتِ الْخَبائِثُ كُلُّها فى بَيْتٍ، وَ جُعِلَ مِفْتاحُها الْكِذْبُ. حديث","fa":"امام عسکری علیه السلام فرمود: تمام پلیدیها در خانه ای گردآمده و کلید آنها دروغگویی قرار داده شده است.","at":"امام حسن عسکری (ع) — چهل حدیث «گهرهای عسکری» (حدیث ۱۳۱۰)"},{"id":"d188","by":"mahdi","ar":"إنَّ اللّهَ تَعالى لَمْ يَخْلُقِ الْخَلْقَ عَبَثاً ولا أهْمَلَهُمْ سُدىً، بَلْ خَلَقَهُمْ بِقُدْرَتِهِ وَ جَعَلَ لَهُمْ أسْماعاً وَ أبْصاراً وَ قُلُوباً وَ ألْباباً، ثُمَّ بَعَثَ اِلَيْهِمُ النَبيّينَ عليهم السلاممُبَشِّرِينَ وَ مُنْذِرينَ،يأمُرُونَهُمْ بِطاعَتِهِ، وَ يَنهُونَهُمْ عَنْ مَعْصيَتِهِ، وَ يُعَرِّفُونَهُمْ ما جَهِلُوهُ مِنْ أمْرِ خالِقِهِمْ وَ دِينِهِمْ. حديث","fa":"حضرت امام مهدی علیه السلام فرمود: خداوند بزرگ مخلوقات را بیهوده نیافریده و آنان را پوچ و بیهوده رها نکرده، بلکه آنان را با قدرت خود آفرید و برای آنان چشم و گوش و قلب و عقل قرار داد و سپس انبیائی که بشارت دهنده و هشدار دهنده هستند به سوی آنان فرستاد که آنان را به اطاعت از او فرمان می دهند و از معصیت او نهی می کنند و چیزهایی را که در مورد پروردگارشان و دینشان نمی دانستند به آنان شناساندند.","at":"امام زمان (عج) — چهل حدیث «گهرهای مهدوی» (حدیث ۱۴۰۱)"},{"id":"d189","by":"mahdi","ar":"ثُمَّ بَعَثَ مُحَمَّداً صلي الله عليه و آله رَحْمَةً لِلْعالَمينَ، وَ تَمَّمَ بِهِ نِعْمَتَهُ وَ خَتَمَ بِهِ أنْبياءَهُ وَ أرْسَلَهُ إلىَ النّاسِ كافَّةً.... حديث","fa":"از امام زمان علیه السلام آمده است که فرمود: سپس خداوند حضرت محمد صلی الله علیه و آله را بعنوان رحمت برای جهانیان بر انگیخت و نعمتش را به وسیله او تمام کرد و پیامبرانش را با او خاتمه بخشید و او را به سوی تمام مردم فرستاد.","at":"امام زمان (عج) — چهل حدیث «گهرهای مهدوی» (حدیث ۱۴۰۲)"},{"id":"d190","by":"mahdi","ar":"وَجَعَلَ الاَْمْرَ بَعْدَهُ صلي الله عليه و آله إلى أخيهِ وَ ابْنِ عَمِّهِ وَ وَصيِّهِ وَ وارِثِهِ عَليِّ بْنِ أبىطالِبٍ ثُمَّ إلىَ الْأوْصياءِ مِن وُلْدِهِ واحِداً واحِداً أحْيا بِهِمْ دينَهُ وَ أتَمَّ بِهِمْ نُورَهُ. حديث","fa":"از حضرت مهدی علیه السلام نقل شده که فرمود: خداوند پس از پیامبر اکرم صلی الله علیه و آله کار امّت را به برادر و پسر عمو و وصیّ و وارث او علی بن ابی طالب علیه السلامسپرد، سپس به جانشینان او از فرزندانش یکی پس از دیگری واگذار کرد. و توسط آنان دین خود را زنده کرد و نور خود را به اتمام رسانید.","at":"امام زمان (عج) — چهل حدیث «گهرهای مهدوی» (حدیث ۱۴۰۳)"},{"id":"d191","by":"mahdi","ar":"وَجَعَلَ بَيْنَهُمْ وَبَيْنَ إخْوانِهِمْ وَ بَنى عَمِّهِمْ وَ الْأدنينَ فَالْأدْنينَ مِنْ ذَوِى أرْحامِهِمْ فُرْقْاناً بَيِّناً يُعْرَفُ بِهِ الْحُجَّةَ مِنَ المْحَجُوج، وَالاْءمامَ مِنَ الْمَأْمُومِ، بِأنْ عَصَمَهُمْ مِنَ الذُّنُوبِ وَبَرَأهُمْ مِنَ الْعيُوبِ وَطَهَّرَهُمْ مِنَ الدَّنَسِ وَ نزَّهَهُمْ مِنَ الْلَّبْسِ وَ جَعَلَهُمْ خُزّانَ عِلْمِهٍ، وَ مُسْتَوْدَعَ حِكْمَتِهِ، وَ مَوْضِعَ سِرِّهِ وَ أيَدَّهُمْ بِالدَّلائلِ، وَ لَوْلا ذلِكَ لَكانَ النّاسُ سَواءً وَ لاَءدَّعى أمْرَاللّهِ عَزَّوَجَلَّ كُلُ اَحَدٍ وَلَما عُرِفَ الحقُّ مِنَ الْباطِلِ وَ لاَ الْعالِمُ مِنَ الْجاهِلِ. حديث","fa":"از حضرت مهدی علیه السلام نقل شده که فرمود: و میان آن امامان و برادرانشان و پسر عموها و خویشان نزدیک آنان تفاوت آشکاری قرار داد تا حجّت خدا از مردم عادی شناخته شود و امام و مأموم از یکدیگر مشخصّ گردد. از این رو آنان را از گناهان و لغزشها و اشتباهات و پلیدیها و عیبها مصون و معصوم قرار داد و آنان را خزینه های علم و حکمت و جایگاه اسرار خود قرار داد و آنان را با دلایل و برهان تأیید کرد و اگر چنین نمی کرد همه مردم برابر بودند و هر کس ادعای رهبری و امامت می کرد و حق و باطل و عالم و نادان تشخیص داده نمی شد.","at":"امام زمان (عج) — چهل حدیث «گهرهای مهدوی» (حدیث ۱۴۰۴)"},{"id":"d192","by":"mahdi","ar":"وَ قَدْ أَبَى اللّهُ عَزَّوَجَلَّ اَنْ يَكُونَ [الإمامَةُ] فى أخَوَيْنِ بَعْدَ الْحَسَنِ وَ الْحُسَيْنِ عليهماالسلام حديث","fa":"از امام علیه السلام چنین آمده است: خداوند بزرگ اجازه نداد و نخواست که امامت پس از امام حسن و امام حسین علیهماالسلام در دو برادر جمع شود.","at":"امام زمان (عج) — چهل حدیث «گهرهای مهدوی» (حدیث ۱۴۰۵)"},{"id":"d193","by":"mahdi","ar":"وَ أمَّا الْأئمَّةُ عليهم السلام فَإنَّهُمْ يَسْألُونَ اللّهَ تَعالى فَيَخْلُقُ وَ يَسْألُونَهُ فَيَرْزُقُ إيجاباً لِمَسْألَتِهِمْ وَ إعْظاماً لِحَقِّهِمْ. حديث","fa":"امام مهدی علیه السلام فرمود: پیشوایان که درود خدا بر آنان باد از خدا درخواست می کنند پس او پدید می آورد و آنان از او می خواهند و او روزی می دهد، بخاطر اجابت درخواست آنان و احترام و بزرگداشت حق آنان.","at":"امام زمان (عج) — چهل حدیث «گهرهای مهدوی» (حدیث ۱۴۰۶)"},{"id":"d194","by":"mahdi","ar":"أوَلَمْ تَروَا أنَّ اللّهَ عَزَّوَجَلَّ جَعَلَ لَكُمْ مَعاقِلَ تَأْوُونَ إلَيْها وَاَعْلاماً تَهْتَدُونَ بِها مِنْ لَدُنْ آدَمَ عليه السلامإلى أنْ ظَهَرَ الْماضى [ابومحمّد ]صَلواتُ اللّهِ عَلَيْهِ. حديث","fa":"از آن حضرت نقل شده که فرمود: آیا نمی بینید که خداوند برای شما منابع عقل را قرار داده که به آن منابع پناه می برید و پرچمها و نشان هایی نصب کرده که بواسطه آنها هدایت می شوید و این روش از زمان حضرت آدم شروع شد تا اینکه امام عسکری علیه السلام که درود خدا بر او باد آشکار شد.","at":"امام زمان (عج) — چهل حدیث «گهرهای مهدوی» (حدیث ۱۴۰۷)"},{"id":"d195","by":"mahdi","ar":"أوَلَمْ يَعُلَمُوا انْتِظامَ أَئِمَّتِهِمْ بَعْدَ نَبيِّهِمْ صلي الله عليه و آلهواحِداً بَعْدَ واحِدٍ إلى أنْ أفْضىَ الْأمْرُ بِأمْرِاللّهِ عَزَّوَجَلَّ إلىَ الماضى يَعْنى الْحَسَنَ بْنَ عَلَىٍّ صَلَواتُ اللّهِ عَلَيْهِ فَقامَ مَقامَ آبائِهِ عليهم السلام يَهْدى إلىَ الْحَقِّ وَ إلى طَريقٍ مُسْتَقيمٍ. حديث","fa":"از امام مهدی علیه السلام آمده است: مگر نمی دانند که امامان آنان بعد از پیامبرشان یکی پس از دیگری به طور منظم آمدند تا به فرمان خدا نوبت به امام پیشین یعنی امام حسن عسکری علیه السلام رسید که به جای پدرانش نشست تا به سوی حق و راه مستقیم رهنمون گردد.","at":"امام زمان (عج) — چهل حدیث «گهرهای مهدوی» (حدیث ۱۴۰۸)"},{"id":"d196","by":"mahdi","ar":"كُلَّما غابَ عَلَمٌ بَدا عَلَمٌ، وَ إذِا أفَلَ نَجْمٌ طَلَعَ نَجْمٌ فَلَمّا قَبَضَهُ اللّهُ إلَيْهِ ظَنَنْتُمْ أنَّ اللّهَ عَزَّوَجَلَّ قَدْ قَطَعَ السَّبَبَ بَيْنَهُ وَ بَيْنَ خَلْقِهِ كَلاّ ما كانَ ذلك وَ لايَكُونُ حَتّى تَقُوَمَ السّاعَةُ وَ يَظْهَرُ أمْرُ اللّهِ عَزَّوَجَلَّ وَ هُمْ كارِهُونَ. حديث","fa":"امام علیه السلام فرمود: هنگامی که پرچمی پنهان شد پرچم دیگری پدیدار گردید، و زمانی که ستاره ای غروب کرد ستاره، دیگری طلوع کرد، زمانی که خداوند امام عسکری علیه السلام را قبض روح کرد. گمان کردید که واسطه و رابطه بین خدا و خلقش قطع شد ولی هرگز رابطه قطع نشد و تا قیامت قطع نخواهد شد و فرمان خدا غالب و پیروز خواهد شد اگر چه آنان دوست نداشته باشند.","at":"امام زمان (عج) — چهل حدیث «گهرهای مهدوی» (حدیث ۱۴۰۹)"},{"id":"d197","by":"mahdi","ar":"أما سَمِعْتُمْ اللّهَ عَزَّوَجَلَّ يَقُولُ: يا اَيُّهَا الَّذينَ امَنوا اَطيعُوا اللّهَ وَ أطيعُوا الرَّسولَ وَ اُولُو الأمْرِ مِنْكُمْ. هَلْ أمرٌ إلاّ بِما هُوَ كائِنٌ إلى يَوْمِ القيامَةِ. حديث","fa":"امام زمان علیه السلام فرمود: آیا شنیدید که خداوند بزرگ فرمود: ای کسانی که ایمان آوردید از خدا و رسول و صاحبان فرمان برخود پیروی و فرمانبرداری کنید، آیا مقصود این نیست فرمانی که تا روز قیامت پا برجاست؟","at":"امام زمان (عج) — چهل حدیث «گهرهای مهدوی» (حدیث ۱۴۱۰)"}]);
